insert into public.recipes (id, name, description, meal_type, main, emoji, prep_time_min, difficulty, calories, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, ingredients, seasonings, instructions, appliances, keywords, dietary_tags, i18n, sort) values
  ('d-chicken-teriyaki-stir-fry', 'Chicken Teriyaki Stir-Fry', 'Chicken, broccoli and peppers in teriyaki sauce over rice', 'dinner', 'chicken', '🍗', 25, 'balanced', 670, 48, 83, 15, 6, 11, 1652, '[{"name":"chicken","amount":160,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"broccoli","amount":120,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"teriyaki","amount":40,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp grated ginger"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the chicken and stir-fry it in the oil over high heat for 5 minutes until browned","Add the broccoli florets, sliced peppers, ginger and a splash of water and cook for 4 minutes","Pour in the teriyaki, toss for 1 minute until glossy and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","chicken","rice","broccoli","peppers","teriyaki","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Стир-фрай с пилешко терияки","description":"Пилешко, броколи и чушки в сос терияки върху ориз","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Нарежете пилешкото на ивици и го запържете в олиото на силен огън за 5 минути, като бъркате, докато се зачерви","Добавете розичките броколи, нарязаните чушки, джинджифила и малко вода и гответе 4 минути","Изсипете соса терияки, разбъркайте 1 минута, докато всичко стане лъскаво, и поднесете върху ориза"],"seasonings":["1 ч.л. настърган джинджифил"]},"nl":{"name":"Roerbak met teriyakikip","description":"Kip, broccoli en paprika in teriyakisaus op rijst","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Snijd de kip in reepjes en roerbak hem 5 minuten in de olie op hoog vuur bruin","Voeg de broccoliroosjes, de paprikareepjes, de gember en een scheutje water toe en bak 4 minuten","Giet de teriyaki erbij, schep 1 minuut om tot alles glanst en serveer op de rijst"],"seasonings":["1 tl geraspte gember"]}}'::jsonb, 60),
  ('d-beef-broccoli-stir-fry', 'Beef and Broccoli Stir-Fry', 'Tender beef strips and broccoli in a garlic soy sauce with rice', 'dinner', 'beef', '🥩', 25, 'balanced', 754, 49, 94, 20, 6, 3, 1244, '[{"name":"beef","amount":160,"unit":"g"},{"name":"rice","amount":100,"unit":"g"},{"name":"broccoli","amount":150,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"soy sauce","amount":20,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp grated ginger","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the beef thinly against the grain and sear it in half the oil over very high heat for 2 minutes, then set it aside","Stir-fry the broccoli florets in the remaining oil with a splash of water for 4 minutes","Return the beef with the chopped garlic, ginger and soy sauce, toss for 1 minute and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","hearty","beef","rice","broccoli","garlic","soy sauce","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Стир-фрай с телешко и броколи","description":"Крехки ивици телешко и броколи в соев сос с чесън, с ориз","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Нарежете телешкото на тънки ивици напречно на влакната, запечатайте го в половината олио на много силен огън за 2 минути и го оставете настрани","Запържете розичките броколи в останалото олио с малко вода за 4 минути, като бъркате","Върнете телешкото с накълцания чесън, джинджифила и соевия сос, разбъркайте 1 минута и поднесете върху ориза"],"seasonings":["1 ч.л. настърган джинджифил","черен пипер"]},"nl":{"name":"Roerbak met rundvlees en broccoli","description":"Malse reepjes rundvlees en broccoli in een knoflook-sojasaus met rijst","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Snijd het rundvlees dwars op de draad in dunne reepjes, schroei het 2 minuten in de helft van de olie op zeer hoog vuur en leg het apart","Roerbak de broccoliroosjes 4 minuten in de rest van de olie met een scheutje water","Doe het vlees terug met de gehakte knoflook, de gember en de sojasaus, schep 1 minuut om en serveer op de rijst"],"seasonings":["1 tl geraspte gember","zwarte peper"]}}'::jsonb, 61),
  ('d-thai-coconut-chicken-curry', 'Thai Coconut Chicken Curry', 'Chicken, peppers and green beans in a spicy coconut sauce with rice', 'dinner', 'chicken', '🍛', 30, 'balanced', 814, 45, 81, 35, 6, 8, 97, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"coconut milk","amount":120,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"green beans","amount":80,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp red curry paste","squeeze of lime juice","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the onion and soften it in the oil for 3 minutes, then fry the curry paste with it for 1 minute","Add the chicken in bite-sized pieces and cook for 3 minutes, then pour in the coconut milk","Add the sliced peppers and halved green beans and simmer for 10 minutes until the chicken is cooked and the beans are tender","Finish with lime juice and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","comfort","hearty","chicken","coconut milk","rice","peppers","green beans","onion","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Тайландско къри с пилешко и кокосово мляко","description":"Пилешко, чушки и зелен фасул в пикантен кокосов сос с ориз","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Нарежете лука на филийки и го задушете в олиото за 3 минути, след което запържете с него къри пастата за 1 минута","Добавете пилешкото на хапки и гответе 3 минути, след което налейте кокосовото мляко","Добавете нарязаните чушки и разрязания наполовина зелен фасул и варете на тих огън 10 минути, докато пилешкото се сготви и фасулът омекне","Овкусете със сок от лайм и поднесете с ориза"],"seasonings":["1 с.л. червена къри паста","няколко капки сок от лайм","сол"]},"nl":{"name":"Thaise kokoscurry met kip","description":"Kip, paprika en sperziebonen in een pittige kokossaus met rijst","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Snijd de ui in ringen en bak hem 3 minuten zacht in de olie; bak dan de currypasta 1 minuut mee","Voeg de kip in hapklare stukjes toe en bak 3 minuten; giet dan de kokosmelk erbij","Voeg de paprikareepjes en de gehalveerde sperziebonen toe en laat 10 minuten zachtjes koken tot de kip gaar is en de bonen zacht zijn","Maak af met limoensap en serveer met de rijst"],"seasonings":["1 el rode currypasta","kneepje limoensap","zout"]}}'::jsonb, 62),
  ('d-garlic-shrimp-noodles', 'Garlic Shrimp Noodles', 'Stir-fried noodles with shrimp, zucchini, carrot and plenty of garlic', 'dinner', 'shrimp', '🍤', 15, 'quick', 638, 48, 74, 17, 6, 7, 1248, '[{"name":"shrimp","amount":160,"unit":"g"},{"name":"noodles","amount":85,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"soy sauce","amount":18,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["black pepper","squeeze of lime juice"]'::jsonb, '["Cook the noodles according to the packet, drain and rinse briefly","Cut the zucchini and carrots into thin strips and stir-fry them in the oil over high heat for 3 minutes","Add the shrimp and sliced garlic and cook for 2 to 3 minutes until the shrimp turn pink","Toss in the noodles and soy sauce, heat through and finish with pepper and lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","shrimp","noodles","zucchini","carrots","garlic","soy sauce","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Нудли със скариди и чесън","description":"Пържени нудли със скариди, тиквичка, морков и много чесън","instructions":["Сварете нудлите според указанията на опаковката, отцедете ги и ги изплакнете набързо","Нарежете тиквичката и морковите на тънки лентички и ги запържете в олиото на силен огън за 3 минути, като бъркате","Добавете скаридите и нарязания чесън и гответе 2–3 минути, докато скаридите порозовеят","Добавете нудлите и соевия сос, затоплете добре и овкусете с пипер и сок от лайм"],"seasonings":["черен пипер","няколко капки сок от лайм"]},"nl":{"name":"Noedels met knoflookgarnalen","description":"Geroerbakte noedels met garnalen, courgette, wortel en veel knoflook","instructions":["Kook de noedels volgens de verpakking, giet af en spoel kort af","Snijd de courgette en de wortels in dunne reepjes en roerbak ze 3 minuten in de olie op hoog vuur","Voeg de garnalen en de plakjes knoflook toe en bak 2 tot 3 minuten tot de garnalen roze kleuren","Schep de noedels en de sojasaus erdoor, warm goed door en maak af met peper en limoensap"],"seasonings":["zwarte peper","kneepje limoensap"]}}'::jsonb, 63),
  ('d-tofu-coconut-curry', 'Tofu Coconut Curry', 'Tofu, spinach and peppers in a spiced coconut sauce with rice', 'dinner', 'tofu', '🥥', 25, 'balanced', 829, 42, 79, 43, 9, 5, 110, '[{"name":"tofu","amount":180,"unit":"g"},{"name":"coconut milk","amount":100,"unit":"g"},{"name":"rice","amount":75,"unit":"g"},{"name":"spinach","amount":80,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry paste","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the onion and peppers and cook them in the oil for 4 minutes, then stir in the curry paste for 1 minute","Add the coconut milk and the tofu, cut into cubes, and simmer gently for 8 minutes","Stir in the spinach until wilted, season with salt and lime juice and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","comfort","hearty","tofu","coconut milk","rice","spinach","peppers","onion","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Къри с тофу и кокосово мляко","description":"Тофу, спанак и чушки в ароматен кокосов сос с ориз","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Нарежете лука и чушките на ивици и ги гответе в олиото 4 минути, след което добавете къри пастата за 1 минута","Добавете кокосовото мляко и нарязаното на кубчета тофу и варете на тих огън 8 минути","Добавете спанака и бъркайте, докато омекне, овкусете със сол и сок от лайм и поднесете с ориза"],"seasonings":["1 с.л. къри паста","сол","няколко капки сок от лайм"]},"nl":{"name":"Kokoscurry met tofu","description":"Tofu, spinazie en paprika in een gekruide kokossaus met rijst","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Snijd de ui en de paprika in reepjes en bak ze 4 minuten in de olie; roer dan 1 minuut de currypasta erdoor","Voeg de kokosmelk en de tofu in blokjes toe en laat 8 minuten zachtjes koken","Roer de spinazie erdoor tot hij geslonken is, breng op smaak met zout en limoensap en serveer met de rijst"],"seasonings":["1 el currypasta","zout","kneepje limoensap"]}}'::jsonb, 64),
  ('d-pork-fried-rice', 'Pork Fried Rice', 'Fried rice with pork, egg, peas and carrot', 'dinner', 'pork', '🍚', 25, 'balanced', 787, 48, 86, 26, 6, 7, 1245, '[{"name":"pork","amount":140,"unit":"g"},{"name":"rice","amount":85,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"peas","amount":60,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"soy sauce","amount":18,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it steam dry","Cut the pork into small strips and fry in the oil over high heat for 4 minutes until browned","Add the diced onion and carrots and the peas and stir-fry for 3 minutes","Push everything aside, scramble the egg in the gap, then add the rice and soy sauce and fry for 2 minutes"]'::jsonb, '["stovetop"]'::jsonb, '["asian","hearty","pork","rice","eggs","peas","carrots","onion","soy sauce","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Пържен ориз със свинско","description":"Пържен ориз със свинско, яйце, грах и морков","instructions":["Сварете ориза в подсолена вода за 10–12 минути, отцедете го и го оставете да изсъхне на парата","Нарежете свинското на малки ивици и го запържете в олиото на силен огън за 4 минути, докато се зачерви","Добавете нарязаните на кубчета лук и моркови и граха и пържете 3 минути, като бъркате","Избутайте всичко настрани, разбъркайте яйцето в празното място, след което добавете ориза и соевия сос и пържете 2 минути"],"seasonings":["черен пипер"]},"nl":{"name":"Gebakken rijst met varkensvlees","description":"Gebakken rijst met varkensvlees, ei, doperwten en wortel","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, giet af en laat hem droog stomen","Snijd het varkensvlees in kleine reepjes en bak ze 4 minuten in de olie op hoog vuur bruin","Voeg de blokjes ui en wortel en de doperwten toe en roerbak 3 minuten","Schuif alles opzij, roer het ei in de vrije ruimte tot roerei, voeg dan de rijst en de sojasaus toe en bak 2 minuten"],"seasonings":["zwarte peper"]}}'::jsonb, 65),
  ('d-teriyaki-salmon-green-beans', 'Teriyaki Salmon with Green Beans', 'Oven-glazed salmon with green beans and rice', 'dinner', 'salmon', '🐟', 25, 'balanced', 721, 41, 79, 26, 4, 10, 1633, '[{"name":"salmon","amount":150,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"teriyaki","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["sesame seeds if you have them"]'::jsonb, '["Heat the oven to 200°C and boil the rice in salted water for 10 to 12 minutes, then drain","Toss the green beans with the oil on a baking tray, put the salmon next to them and brush it with half the teriyaki","Roast for 12 minutes until the salmon flakes easily","Brush the salmon with the remaining teriyaki and serve with the beans and rice"]'::jsonb, '["stovetop","oven"]'::jsonb, '["asian","salmon","rice","green beans","teriyaki","oil","stovetop","oven","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Сьомга терияки със зелен фасул","description":"Глазирана на фурна сьомга със зелен фасул и ориз","instructions":["Загрейте фурната на 200°C и сварете ориза в подсолена вода за 10–12 минути, след което го отцедете","Разбъркайте зеления фасул с олиото в тава, сложете сьомгата до него и я намажете с половината сос терияки","Печете 12 минути, докато сьомгата започне лесно да се разделя на парченца","Намажете сьомгата с останалия сос терияки и поднесете с фасула и ориза"],"seasonings":["сусам, ако имате"]},"nl":{"name":"Teriyakizalm met sperziebonen","description":"In de oven geglaceerde zalm met sperziebonen en rijst","instructions":["Verwarm de oven voor op 200°C en kook de rijst 10 tot 12 minuten in water met zout; giet af","Meng de sperziebonen met de olie op een bakplaat, leg de zalm ernaast en bestrijk hem met de helft van de teriyaki","Rooster 12 minuten tot de zalm makkelijk uit elkaar valt","Bestrijk de zalm met de rest van de teriyaki en serveer met de bonen en de rijst"],"seasonings":["sesamzaad als je het hebt"]}}'::jsonb, 66),
  ('d-chicken-chow-mein', 'Chicken Chow Mein', 'Stir-fried noodles with chicken, carrot, peppers and onion', 'dinner', 'chicken', '🍜', 20, 'quick', 679, 49, 75, 20, 7, 9, 1229, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"noodles","amount":85,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"soy sauce","amount":20,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp grated ginger","black pepper"]'::jsonb, '["Cook the noodles according to the packet, drain and rinse briefly","Slice the chicken thinly and stir-fry it in the oil over high heat for 4 minutes","Add the sliced onion, peppers and carrots and the ginger and cook for 3 minutes","Add the noodles and soy sauce and toss over the heat for 2 minutes"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","chicken","noodles","carrots","peppers","onion","soy sauce","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Чоу мейн с пилешко","description":"Пържени нудли с пилешко, морков, чушки и лук","instructions":["Сварете нудлите според указанията на опаковката, отцедете ги и ги изплакнете набързо","Нарежете пилешкото на тънки ивици и го запържете в олиото на силен огън за 4 минути, като бъркате","Добавете нарязаните лук, чушки и моркови и джинджифила и гответе 3 минути","Добавете нудлите и соевия сос и бъркайте на огъня 2 минути"],"seasonings":["1 ч.л. настърган джинджифил","черен пипер"]},"nl":{"name":"Chow mein met kip","description":"Geroerbakte noedels met kip, wortel, paprika en ui","instructions":["Kook de noedels volgens de verpakking, giet af en spoel kort af","Snijd de kip in dunne reepjes en roerbak hem 4 minuten in de olie op hoog vuur","Voeg de reepjes ui, paprika en wortel en de gember toe en bak 3 minuten","Voeg de noedels en de sojasaus toe en schep 2 minuten om op het vuur"],"seasonings":["1 tl geraspte gember","zwarte peper"]}}'::jsonb, 67),
  ('d-spicy-beef-green-bean-rice', 'Spicy Beef and Green Bean Rice Bowl', 'Chili-garlic beef mince with blistered green beans over rice', 'dinner', 'beef mince', '🌶️', 20, 'quick', 717, 38, 76, 28, 5, 4, 1100, '[{"name":"beef mince","amount":150,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"soy sauce","amount":18,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp chili flakes","1 tsp grated ginger"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Fry the green beans, cut into short lengths, in the oil over high heat for 4 minutes until blistered, then set aside","Brown the beef mince in the same pan for 5 minutes, then add the chopped garlic, ginger and chili flakes","Return the beans, add the soy sauce, toss for 1 minute and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","quick","beef mince","rice","green beans","garlic","soy sauce","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пикантна купа ориз с телешка кайма и зелен фасул","description":"Телешка кайма с чили и чесън и запечен зелен фасул върху ориз","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Запържете зеления фасул, нарязан на къси парчета, в олиото на силен огън за 4 минути, докато се набръчка, и го оставете настрани","Запържете телешката кайма в същия тиган за 5 минути, след което добавете накълцания чесън, джинджифила и люспите чили","Върнете фасула, добавете соевия сос, разбъркайте 1 минута и поднесете върху ориза"],"seasonings":["1 ч.л. люспи чили","1 ч.л. настърган джинджифил"]},"nl":{"name":"Pittige rijstkom met rundergehakt en sperziebonen","description":"Rundergehakt met chili en knoflook en geblakerde sperziebonen op rijst","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Bak de sperziebonen, in korte stukjes gesneden, 4 minuten in de olie op hoog vuur tot ze blaasjes krijgen en leg ze apart","Bak het rundergehakt 5 minuten bruin in dezelfde pan en voeg dan de gehakte knoflook, de gember en de chilivlokken toe","Doe de bonen terug, voeg de sojasaus toe, schep 1 minuut om en serveer op de rijst"],"seasonings":["1 tl chilivlokken","1 tl geraspte gember"]}}'::jsonb, 68),
  ('d-turkey-zucchini-stir-fry', 'Turkey and Zucchini Stir-Fry', 'Lean turkey mince stir-fried with zucchini and carrot, served with rice', 'dinner', 'turkey mince', '🥒', 20, 'quick', 600, 38, 66, 21, 4, 7, 969, '[{"name":"turkey mince","amount":150,"unit":"g"},{"name":"rice","amount":65,"unit":"g"},{"name":"zucchini","amount":150,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp grated ginger","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Brown the turkey mince in the oil over high heat for 5 minutes, breaking it up","Add the zucchini in half-moons, the carrots in thin strips, the chopped garlic and the ginger and stir-fry for 4 minutes","Stir in the soy sauce and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","turkey mince","rice","zucchini","carrots","soy sauce","garlic","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Стир-фрай с пуешка кайма и тиквичка","description":"Постна пуешка кайма, запържена с тиквичка и морков, с ориз","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Запържете пуешката кайма в олиото на силен огън за 5 минути, като я разбивате на трохи","Добавете тиквичката на полумесеци, морковите на тънки лентички, накълцания чесън и джинджифила и пържете 4 минути, като бъркате","Добавете соевия сос, разбъркайте и поднесете върху ориза"],"seasonings":["1 ч.л. настърган джинджифил","черен пипер"]},"nl":{"name":"Roerbak met kalkoen en courgette","description":"Mager kalkoengehakt geroerbakt met courgette en wortel, met rijst","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Bak het kalkoengehakt 5 minuten bruin in de olie op hoog vuur en maak het los","Voeg de courgette in halve plakjes, de wortels in dunne reepjes, de gehakte knoflook en de gember toe en roerbak 4 minuten","Roer de sojasaus erdoor en serveer op de rijst"],"seasonings":["1 tl geraspte gember","zwarte peper"]}}'::jsonb, 69),
  ('d-vegetable-egg-fried-rice', 'Vegetable Egg Fried Rice', 'Big bowl of fried rice with three eggs, peas, corn and carrot', 'dinner', 'eggs', '🍳', 20, 'quick', 770, 34, 92, 29, 7, 9, 1440, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"rice","amount":85,"unit":"g"},{"name":"peas","amount":70,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"soy sauce","amount":18,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it steam dry","Dice the carrots and fry them in the oil over high heat for 3 minutes, then add the peas and corn","Push the vegetables aside, crack in the eggs and scramble until just set","Add the rice and soy sauce and stir-fry for 2 to 3 minutes"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","hearty","eggs","rice","peas","corn","carrots","soy sauce","oil","stovetop","dinner"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пържен ориз с яйца и зеленчуци","description":"Голяма купа пържен ориз с три яйца, грах, царевица и морков","instructions":["Сварете ориза в подсолена вода за 10–12 минути, отцедете го и го оставете да изсъхне на парата","Нарежете морковите на кубчета и ги запържете в олиото на силен огън за 3 минути, след което добавете граха и царевицата","Избутайте зеленчуците настрани, чукнете яйцата и ги бъркайте, докато едва стегнат","Добавете ориза и соевия сос и пържете 2–3 минути, като бъркате"],"seasonings":["черен пипер"]},"nl":{"name":"Gebakken rijst met ei en groenten","description":"Grote kom gebakken rijst met drie eieren, doperwten, mais en wortel","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, giet af en laat hem droog stomen","Snijd de wortels in blokjes en bak ze 3 minuten in de olie op hoog vuur; voeg dan de doperwten en de mais toe","Schuif de groenten opzij, breek de eieren in de pan en roer ze tot ze net gestold zijn","Voeg de rijst en de sojasaus toe en roerbak 2 tot 3 minuten"],"seasonings":["zwarte peper"]}}'::jsonb, 70),
  ('d-soy-ginger-fish', 'Soy-Ginger Fish with Rice', 'Gently steamed white fish with spinach, carrot and a soy-ginger sauce', 'dinner', 'white fish', '🐟', 20, 'quick', 507, 40, 69, 7, 5, 3, 1041, '[{"name":"white fish","amount":170,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"spinach","amount":100,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp grated ginger","3 tbsp water"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Warm the oil in a lidded pan and soften the sliced garlic, ginger and thinly sliced carrots for 2 minutes","Lay the fish on top, add the soy sauce and water, cover and steam over low heat for 6 to 8 minutes","Add the spinach for the last minute and serve everything over the rice with the pan juices"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","white fish","rice","spinach","carrots","soy sauce","garlic","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Риба със соев сос и джинджифил и ориз","description":"Леко задушена бяла риба със спанак, морков и сос от соя и джинджифил","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Затоплете олиото в тиган с капак и задушете нарязания чесън, джинджифила и тънко нарязаните моркови за 2 минути","Сложете рибата отгоре, добавете соевия сос и водата, покрийте и задушете на слаб огън 6–8 минути","Добавете спанака през последната минута и поднесете всичко върху ориза със соса от тигана"],"seasonings":["1 с.л. настърган джинджифил","3 с.л. вода"]},"nl":{"name":"Vis met soja en gember en rijst","description":"Zacht gestoomde witvis met spinazie, wortel en een soja-gembersaus","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Verwarm de olie in een pan met deksel en bak de plakjes knoflook, de gember en de dunne plakjes wortel 2 minuten zacht","Leg de vis erop, voeg de sojasaus en het water toe, dek af en stoom 6 tot 8 minuten op laag vuur","Voeg de laatste minuut de spinazie toe en serveer alles op de rijst met het kookvocht uit de pan"],"seasonings":["1 el geraspte gember","3 el water"]}}'::jsonb, 71),
  ('d-coconut-lentil-dal', 'Coconut Lentil Dal', 'Creamy spiced lentils with tomato, spinach and coconut, served with rice', 'dinner', 'lentils', '🍲', 35, 'balanced', 777, 30, 116, 24, 15, 8, 257, '[{"name":"lentils","amount":80,"unit":"g"},{"name":"coconut milk","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"spinach","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"rice","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","1/2 tsp chili flakes","{350} ml water","salt"]'::jsonb, '["Dice the onion and soften it in the oil for 4 minutes, then add the chopped garlic, curry powder and chili flakes for 1 minute","Add the rinsed lentils, chopped tomatoes and water and simmer for 20 to 25 minutes until the lentils are soft","Meanwhile boil the rice in salted water for 10 to 12 minutes and drain","Stir the coconut milk and spinach into the lentils, cook 2 more minutes, season with salt and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","comfort","hearty","lentils","coconut milk","chopped tomatoes","spinach","onion","garlic","rice","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Дал от леща с кокосово мляко","description":"Кремообразна леща с подправки, домати, спанак и кокосово мляко, с ориз","instructions":["Нарежете лука на кубчета и го задушете в олиото за 4 минути, след което добавете накълцания чесън, кърито и люспите чили за 1 минута","Добавете измитата леща, нарязаните домати и водата и варете на тих огън 20–25 минути, докато лещата омекне","Междувременно сварете ориза в подсолена вода за 10–12 минути и го отцедете","Добавете кокосовото мляко и спанака към лещата, варете още 2 минути, овкусете със сол и поднесете с ориза"],"seasonings":["1 с.л. къри на прах","1/2 ч.л. люспи чили","{350} мл вода","сол"]},"nl":{"name":"Linzendal met kokos","description":"Romige gekruide linzen met tomaat, spinazie en kokos, met rijst","instructions":["Snijd de ui in blokjes en bak hem 4 minuten zacht in de olie; voeg dan de gehakte knoflook, het kerriepoeder en de chilivlokken 1 minuut toe","Voeg de afgespoelde linzen, de tomatenblokjes en het water toe en laat 20 tot 25 minuten zachtjes koken tot de linzen zacht zijn","Kook intussen de rijst 10 tot 12 minuten in water met zout en giet af","Roer de kokosmelk en de spinazie door de linzen, kook nog 2 minuten, breng op smaak met zout en serveer met de rijst"],"seasonings":["1 el kerriepoeder","1/2 tl chilivlokken","{350} ml water","zout"]}}'::jsonb, 72),
  ('d-chili-con-carne', 'Chili con Carne', 'Slow-simmered beef and bean chili with rice', 'dinner', 'beef mince', '🌶️', 40, 'balanced', 848, 45, 100, 30, 13, 14, 570, '[{"name":"beef mince","amount":150,"unit":"g"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"rice","amount":75,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","salt"]'::jsonb, '["Soften the diced onion and peppers in the oil for 5 minutes, then add the beef mince and brown it for 5 minutes","Stir in the chopped garlic, cumin, paprika and chili flakes for 1 minute","Add the chopped tomatoes and drained kidney beans and simmer gently for 20 minutes until thick","Meanwhile boil the rice in salted water for 10 to 12 minutes, drain and serve with the chili"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","hearty","beef mince","kidney beans","chopped tomatoes","onion","peppers","rice","garlic","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Чили кон карне","description":"Бавно сготвено чили от телешка кайма и боб с ориз","instructions":["Задушете нарязаните на кубчета лук и чушки в олиото за 5 минути, след което добавете телешката кайма и я запържете 5 минути","Добавете накълцания чесън, кимиона, червения пипер и люспите чили и бъркайте 1 минута","Добавете нарязаните домати и отцедения червен боб и варете на тих огън 20 минути, докато се сгъсти","Междувременно сварете ориза в подсолена вода за 10–12 минути, отцедете го и го поднесете с чилито"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","1/2 ч.л. люспи чили","сол"]},"nl":{"name":"Chili con carne","description":"Langzaam gestoofde chili van rundergehakt en bonen met rijst","instructions":["Bak de blokjes ui en paprika 5 minuten zacht in de olie, voeg dan het rundergehakt toe en bak het 5 minuten bruin","Roer 1 minuut de gehakte knoflook, de komijn, het paprikapoeder en de chilivlokken erdoor","Voeg de tomatenblokjes en de uitgelekte kidneybonen toe en laat 20 minuten zachtjes koken tot de chili dik is","Kook intussen de rijst 10 tot 12 minuten in water met zout, giet af en serveer met de chili"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","1/2 tl chilivlokken","zout"]}}'::jsonb, 73),
  ('d-chicken-enchiladas', 'Chicken Enchiladas', 'Tortillas rolled around chicken and peppers, baked in tomato sauce with cheese', 'dinner', 'chicken', '🫔', 40, 'balanced', 810, 55, 81, 30, 9, 17, 1320, '[{"name":"chicken","amount":140,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"tomato sauce","amount":150,"unit":"g"},{"name":"cheese","amount":40,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt"]'::jsonb, '["Heat the oven to 200°C","Fry the chicken in small pieces with the diced onion and peppers in the oil for 7 minutes, then stir in the cumin, paprika, salt and a third of the tomato sauce","Divide the filling between the tortillas, roll them up and place them seam side down in a small baking dish","Pour over the remaining tomato sauce, scatter with the grated cheese and bake for 15 minutes until bubbling"]'::jsonb, '["stovetop","oven"]'::jsonb, '["mexican","comfort","hearty","chicken","tortilla","tomato sauce","cheese","onion","peppers","oil","stovetop","oven","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Енчилади с пилешко","description":"Тортили, навити около пилешко и чушки и запечени в доматен сос с кашкавал","instructions":["Загрейте фурната на 200°C","Запържете пилешкото на малки парчета с нарязаните на кубчета лук и чушки в олиото за 7 минути, след което добавете кимиона, червения пипер, сол и една трета от доматения сос","Разпределете плънката върху тортилите, навийте ги и ги наредете с ръба надолу в малка тава","Залейте с останалия доматен сос, поръсете с настъргания кашкавал и печете 15 минути, докато започне да къкри"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол"]},"nl":{"name":"Enchilada''s met kip","description":"Tortilla''s gerold om kip en paprika, gebakken in tomatensaus met kaas","instructions":["Verwarm de oven voor op 200°C","Bak de kip in kleine stukjes 7 minuten met de blokjes ui en paprika in de olie en roer dan de komijn, het paprikapoeder, zout en een derde van de tomatensaus erdoor","Verdeel de vulling over de tortilla''s, rol ze op en leg ze met de naad naar beneden in een kleine ovenschaal","Giet de rest van de tomatensaus erover, bestrooi met de geraspte kaas en bak 15 minuten tot het bubbelt"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","zout"]}}'::jsonb, 74),
  ('d-beef-bean-burritos', 'Beef and Bean Burritos', 'Tortillas filled with spiced beef mince, kidney beans, cheese and tomato', 'dinner', 'beef mince', '🌯', 25, 'balanced', 862, 48, 83, 37, 10, 11, 1363, '[{"name":"beef mince","amount":130,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"cheese","amount":25,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"onion","amount":40,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt"]'::jsonb, '["Brown the beef mince with the diced onion in a dry pan over high heat for 6 minutes","Add the cumin, paprika, salt, the drained kidney beans and a splash of water and cook for 3 minutes","Warm the tortillas in a dry pan","Fill them with the beef and beans, grated cheese and diced tomato, fold in the sides and roll up tightly"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","hearty","beef mince","tortilla","kidney beans","cheese","tomato","onion","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Бурито с телешка кайма и боб","description":"Тортили с телешка кайма с подправки, червен боб, кашкавал и домат","instructions":["Запържете телешката кайма с нарязания на кубчета лук в сух тиган на силен огън за 6 минути","Добавете кимиона, червения пипер, сол, отцедения червен боб и малко вода и гответе 3 минути","Затоплете тортилите в сух тиган","Напълнете ги с каймата и боба, настъргания кашкавал и нарязания на кубчета домат, подгънете краищата и навийте стегнато"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол"]},"nl":{"name":"Burrito''s met rundergehakt en bonen","description":"Tortilla''s gevuld met gekruid rundergehakt, kidneybonen, kaas en tomaat","instructions":["Bak het rundergehakt met de blokjes ui 6 minuten bruin in een droge pan op hoog vuur","Voeg de komijn, het paprikapoeder, zout, de uitgelekte kidneybonen en een scheutje water toe en bak 3 minuten","Verwarm de tortilla''s in een droge pan","Vul ze met het gehakt en de bonen, de geraspte kaas en de tomatenblokjes, vouw de zijkanten naar binnen en rol strak op"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","zout"]}}'::jsonb, 75),
  ('d-fish-tacos', 'Fish Tacos', 'Pan-fried white fish in tortillas with lettuce, tomato and a lime yogurt sauce', 'dinner', 'white fish', '🐟', 20, 'quick', 625, 43, 66, 20, 6, 9, 1001, '[{"name":"white fish","amount":170,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp paprika","1/2 tsp ground cumin","salt","squeeze of lime juice"]'::jsonb, '["Season the fish with the paprika, cumin and salt and fry in the oil over medium-high heat for 3 minutes per side, then break into large flakes","Stir lime juice and a pinch of salt into the yogurt","Warm the tortillas in a dry pan","Fill them with shredded lettuce, the fish and diced tomato and drizzle with the yogurt sauce"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","fresh","quick","light","white fish","tortilla","lettuce","tomato","yogurt","oil","stovetop","dinner"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Такос с риба","description":"Бяла риба на тиган в тортили с маруля, домат и сос от кисело мляко и лайм","instructions":["Овкусете рибата с червения пипер, кимиона и сол и я изпържете в олиото на умерено силен огън по 3 минути от всяка страна, след което я разделете на едри парчета","Разбъркайте сок от лайм и щипка сол в киселото мляко","Затоплете тортилите в сух тиган","Напълнете ги с нарязаната маруля, рибата и нарязания на кубчета домат и полейте със соса от кисело мляко"],"seasonings":["1 ч.л. червен пипер","1/2 ч.л. смлян кимион","сол","няколко капки сок от лайм"]},"nl":{"name":"Vistaco''s","description":"Gebakken witvis in tortilla''s met sla, tomaat en een limoen-yoghurtsaus","instructions":["Kruid de vis met het paprikapoeder, de komijn en zout, bak hem in de olie op middelhoog tot hoog vuur 3 minuten per kant en trek hem in grote stukken","Roer limoensap en een snufje zout door de yoghurt","Verwarm de tortilla''s in een droge pan","Vul ze met de gesneden sla, de vis en de tomatenblokjes en besprenkel met de yoghurtsaus"],"seasonings":["1 tl paprikapoeder","1/2 tl gemalen komijn","zout","kneepje limoensap"]}}'::jsonb, 76),
  ('d-sweet-potato-bean-chili', 'Sweet Potato and Bean Chili', 'Thick vegan chili with sweet potato, kidney beans, peppers and corn', 'dinner', 'kidney beans', '🍠', 35, 'balanced', 539, 19, 97, 11, 22, 27, 795, '[{"name":"sweet potato","amount":200,"unit":"g"},{"name":"kidney beans","amount":150,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp smoked paprika","1/2 tsp chili flakes","{150} ml water","salt"]'::jsonb, '["Soften the diced onion and peppers in the oil for 5 minutes, then stir in the cumin, paprika and chili flakes","Add the sweet potato in 2 cm cubes, the chopped tomatoes and the water and simmer, covered, for 20 minutes until the sweet potato is tender","Stir in the drained kidney beans and corn and cook for 5 more minutes","Season with salt"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","light","sweet potato","kidney beans","chopped tomatoes","onion","peppers","corn","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Чили със сладък картоф и боб","description":"Гъсто веган чили със сладък картоф, червен боб, чушки и царевица","instructions":["Задушете нарязаните на кубчета лук и чушки в олиото за 5 минути, след което добавете кимиона, червения пипер и люспите чили","Добавете сладкия картоф на кубчета от 2 см, нарязаните домати и водата и варете под капак на тих огън 20 минути, докато сладкият картоф омекне","Добавете отцедения червен боб и царевицата и варете още 5 минути","Овкусете със сол"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. пушен червен пипер","1/2 ч.л. люспи чили","{150} мл вода","сол"]},"nl":{"name":"Chili met zoete aardappel en bonen","description":"Dikke vegan chili met zoete aardappel, kidneybonen, paprika en mais","instructions":["Bak de blokjes ui en paprika 5 minuten zacht in de olie en roer dan de komijn, het paprikapoeder en de chilivlokken erdoor","Voeg de zoete aardappel in blokjes van 2 cm, de tomatenblokjes en het water toe en laat 20 minuten met het deksel op de pan zachtjes koken tot de zoete aardappel gaar is","Roer de uitgelekte kidneybonen en de mais erdoor en kook nog 5 minuten","Breng op smaak met zout"],"seasonings":["1 tl gemalen komijn","1 tl gerookt paprikapoeder","1/2 tl chilivlokken","{150} ml water","zout"]}}'::jsonb, 77),
  ('d-loaded-chicken-burrito-bowl', 'Loaded Chicken Burrito Bowl', 'Rice bowl with spiced chicken, beans, corn, tomato and avocado', 'dinner', 'chicken', '🥑', 25, 'balanced', 906, 53, 105, 32, 17, 9, 398, '[{"name":"chicken","amount":160,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":80,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Coat the chicken, cut into strips, with the cumin, paprika and salt and fry in the oil for 7 minutes until cooked through","Warm the drained kidney beans and corn in the pan for 1 minute","Serve the rice topped with the chicken, beans, corn, diced tomato and sliced avocado, with lime juice squeezed over"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","hearty","chicken","rice","kidney beans","corn","avocado","tomato","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Богата бурито купа с пилешко","description":"Купа ориз с пилешко с подправки, боб, царевица, домат и авокадо","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Овкусете пилешкото, нарязано на ивици, с кимиона, червения пипер и сол и го запържете в олиото за 7 минути, докато се сготви","Затоплете отцедения червен боб и царевицата в тигана за 1 минута","Поднесете ориза с пилешкото, боба, царевицата, нарязания на кубчета домат и нарязаното авокадо отгоре и изстискайте сок от лайм"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол","няколко капки сок от лайм"]},"nl":{"name":"Rijk gevulde burritobowl met kip","description":"Rijstkom met gekruide kip, bonen, mais, tomaat en avocado","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Wentel de kip, in reepjes gesneden, door de komijn, het paprikapoeder en zout en bak hem 7 minuten in de olie tot hij gaar is","Verwarm de uitgelekte kidneybonen en de mais 1 minuut in de pan","Serveer de rijst met de kip, de bonen, de mais, de tomatenblokjes en de plakjes avocado erop en knijp er limoensap over"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","zout","kneepje limoensap"]}}'::jsonb, 78),
  ('d-pork-tacos-corn-salsa', 'Pork Tacos with Corn Salsa', 'Seared pork strips in tortillas with a fresh corn and tomato salsa', 'dinner', 'pork', '🌮', 20, 'quick', 719, 44, 74, 27, 7, 10, 1089, '[{"name":"pork","amount":150,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"corn","amount":60,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Mix the corn with the diced tomato, finely diced onion, lime juice and a pinch of salt","Cut the pork into thin strips and coat with the cumin, paprika and salt","Fry the pork in the oil over high heat for 4 to 5 minutes until browned and cooked through","Warm the tortillas and fill them with the pork and salsa"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","pork","tortilla","corn","tomato","onion","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Такос със свинско и салса от царевица","description":"Запечатани ивици свинско в тортили със свежа салса от царевица и домат","instructions":["Смесете царевицата с нарязания на кубчета домат, ситно нарязания лук, сока от лайм и щипка сол","Нарежете свинското на тънки ивици и го овкусете с кимиона, червения пипер и сол","Запържете свинското в олиото на силен огън за 4–5 минути, докато се зачерви и се сготви","Затоплете тортилите и ги напълнете със свинското и салсата"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол","няколко капки сок от лайм"]},"nl":{"name":"Taco''s met varkensvlees en maissalsa","description":"Aangebakken reepjes varkensvlees in tortilla''s met een frisse salsa van mais en tomaat","instructions":["Meng de mais met de tomatenblokjes, de fijngesneden ui, het limoensap en een snufje zout","Snijd het varkensvlees in dunne reepjes en wentel ze door de komijn, het paprikapoeder en zout","Bak het vlees 4 tot 5 minuten in de olie op hoog vuur bruin en gaar","Verwarm de tortilla''s en vul ze met het vlees en de salsa"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","zout","kneepje limoensap"]}}'::jsonb, 79),
  ('d-shrimp-fajitas', 'Shrimp Fajitas', 'Sizzling shrimp with peppers and onion in warm tortillas', 'dinner', 'shrimp', '🍤', 15, 'quick', 638, 46, 72, 19, 8, 12, 1093, '[{"name":"shrimp","amount":170,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"peppers","amount":120,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","salt","squeeze of lime juice"]'::jsonb, '["Slice the peppers and onion and fry them in the oil over high heat for 5 minutes until soft and charred at the edges","Add the shrimp with the cumin, paprika, chili flakes and salt and cook for 2 to 3 minutes until pink","Warm the tortillas in a dry pan","Fill them with the shrimp and vegetables and squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","light","shrimp","tortilla","peppers","onion","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Фахитас със скариди","description":"Цвърчащи скариди с чушки и лук в топли тортили","instructions":["Нарежете чушките и лука на ивици и ги запържете в олиото на силен огън за 5 минути, докато омекнат и прегорят леко по краищата","Добавете скаридите с кимиона, червения пипер, люспите чили и сол и гответе 2–3 минути, докато порозовеят","Затоплете тортилите в сух тиган","Напълнете ги със скаридите и зеленчуците и изстискайте сок от лайм"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","1/2 ч.л. люспи чили","сол","няколко капки сок от лайм"]},"nl":{"name":"Fajita''s met garnalen","description":"Sissende garnalen met paprika en ui in warme tortilla''s","instructions":["Snijd de paprika en de ui in reepjes en bak ze 5 minuten in de olie op hoog vuur tot ze zacht zijn met geblakerde randjes","Voeg de garnalen met de komijn, het paprikapoeder, de chilivlokken en zout toe en bak 2 tot 3 minuten tot ze roze zijn","Verwarm de tortilla''s in een droge pan","Vul ze met de garnalen en de groenten en knijp er limoensap over"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","1/2 tl chilivlokken","zout","kneepje limoensap"]}}'::jsonb, 80),
  ('d-turkey-bean-chili', 'Turkey and Bean Chili', 'Lean turkey mince chili with kidney beans and peppers, served with rice', 'dinner', 'turkey mince', '🦃', 35, 'balanced', 682, 45, 86, 19, 13, 14, 556, '[{"name":"turkey mince","amount":150,"unit":"g"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","salt"]'::jsonb, '["Soften the diced onion and peppers in the oil for 5 minutes, then add the turkey mince and brown it for 5 minutes","Stir in the cumin, paprika and chili flakes, then the chopped tomatoes and drained kidney beans","Simmer for 15 minutes until thick and season with salt","Meanwhile boil the rice in salted water for 10 to 12 minutes, drain and serve with the chili"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","turkey mince","kidney beans","chopped tomatoes","peppers","onion","rice","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Чили с пуешка кайма и боб","description":"Чили от постна пуешка кайма с червен боб и чушки, с ориз","instructions":["Задушете нарязаните на кубчета лук и чушки в олиото за 5 минути, след което добавете пуешката кайма и я запържете 5 минути","Добавете кимиона, червения пипер и люспите чили, а след тях нарязаните домати и отцедения червен боб","Варете на тих огън 15 минути, докато се сгъсти, и овкусете със сол","Междувременно сварете ориза в подсолена вода за 10–12 минути, отцедете го и го поднесете с чилито"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","1/2 ч.л. люспи чили","сол"]},"nl":{"name":"Chili met kalkoen en bonen","description":"Chili van mager kalkoengehakt met kidneybonen en paprika, met rijst","instructions":["Bak de blokjes ui en paprika 5 minuten zacht in de olie, voeg dan het kalkoengehakt toe en bak het 5 minuten bruin","Roer de komijn, het paprikapoeder en de chilivlokken erdoor en dan de tomatenblokjes en de uitgelekte kidneybonen","Laat 15 minuten zachtjes koken tot de chili dik is en breng op smaak met zout","Kook intussen de rijst 10 tot 12 minuten in water met zout, giet af en serveer met de chili"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","1/2 tl chilivlokken","zout"]}}'::jsonb, 81),
  ('d-mexican-stuffed-peppers', 'Mexican Stuffed Peppers', 'Peppers filled with mince, rice and corn, baked with cheese', 'dinner', 'mixed mince', '🫑', 50, 'weekend', 705, 37, 70, 32, 8, 17, 456, '[{"name":"peppers","amount":250,"unit":"g"},{"name":"mixed mince","amount":120,"unit":"g"},{"name":"rice","amount":50,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"tomato sauce","amount":80,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt"]'::jsonb, '["Heat the oven to 200°C and boil the rice in salted water for 10 minutes, then drain","Brown the mince in a dry pan for 5 minutes and stir in the cumin, paprika, salt, corn, rice and tomato sauce","Halve the peppers lengthways and scoop out the seeds. Fill the pepper halves with the mixture","Place in a baking dish, cover with foil and bake for 20 minutes, then uncover, top with the grated cheese and bake 10 more minutes"]'::jsonb, '["stovetop","oven"]'::jsonb, '["mexican","comfort","peppers","mixed mince","rice","corn","cheese","tomato sauce","stovetop","oven","dinner"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Пълнени чушки по мексикански","description":"Чушки, пълнени с кайма, ориз и царевица и запечени с кашкавал","instructions":["Загрейте фурната на 200°C и сварете ориза в подсолена вода за 10 минути, след което го отцедете","Запържете каймата в сух тиган за 5 минути и добавете кимиона, червения пипер, сол, царевицата, ориза и доматения сос","Разрежете чушките по дължина и извадете семките. Напълнете половинките със сместа","Наредете ги в тава, покрийте с фолио и печете 20 минути, след което махнете фолиото, поръсете с настъргания кашкавал и печете още 10 минути"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол"]},"nl":{"name":"Mexicaanse gevulde paprika''s","description":"Paprika''s gevuld met gehakt, rijst en mais, gebakken met kaas","instructions":["Verwarm de oven voor op 200°C en kook de rijst 10 minuten in water met zout; giet af","Bak het gehakt 5 minuten bruin in een droge pan en roer de komijn, het paprikapoeder, zout, de mais, de rijst en de tomatensaus erdoor","Halveer de paprika''s in de lengte en verwijder de zaadjes. Vul de halve paprika''s met het mengsel","Zet ze in een ovenschaal, dek af met aluminiumfolie en bak 20 minuten; haal de folie eraf, bestrooi met de geraspte kaas en bak nog 10 minuten"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","zout"]}}'::jsonb, 82),
  ('d-tofu-bean-tacos', 'Tofu and Bean Tacos', 'Crumbled spiced tofu and kidney beans in tortillas with tomato and lettuce', 'dinner', 'tofu', '🌮', 20, 'quick', 774, 43, 85, 32, 14, 10, 1096, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"lettuce","amount":40,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp smoked paprika","1/2 tsp chili flakes","salt","squeeze of lime juice"]'::jsonb, '["Crumble the tofu into the hot oil and fry over medium-high heat for 6 minutes until golden","Add the cumin, paprika, chili flakes, salt and drained kidney beans and cook for 2 minutes","Warm the tortillas in a dry pan","Fill them with the tofu and beans, diced tomato and shredded lettuce and finish with lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","hearty","tofu","tortilla","kidney beans","tomato","lettuce","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Такос с тофу и боб","description":"Натрошено тофу с подправки и червен боб в тортили с домат и маруля","instructions":["Натрошете тофуто в горещото олио и го запържете на умерено силен огън за 6 минути до златисто","Добавете кимиона, червения пипер, люспите чили, сол и отцедения червен боб и гответе 2 минути","Затоплете тортилите в сух тиган","Напълнете ги с тофуто и боба, нарязания на кубчета домат и нарязаната маруля и овкусете със сок от лайм"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. пушен червен пипер","1/2 ч.л. люспи чили","сол","няколко капки сок от лайм"]},"nl":{"name":"Taco''s met tofu en bonen","description":"Verkruimelde gekruide tofu en kidneybonen in tortilla''s met tomaat en sla","instructions":["Verkruimel de tofu boven de hete olie en bak hem 6 minuten op middelhoog tot hoog vuur goudbruin","Voeg de komijn, het paprikapoeder, de chilivlokken, zout en de uitgelekte kidneybonen toe en bak 2 minuten","Verwarm de tortilla''s in een droge pan","Vul ze met de tofu en de bonen, de tomatenblokjes en de gesneden sla en maak af met limoensap"],"seasonings":["1 tl gemalen komijn","1 tl gerookt paprikapoeder","1/2 tl chilivlokken","zout","kneepje limoensap"]}}'::jsonb, 83),
  ('d-chicken-quesadillas', 'Chicken Quesadillas', 'Crisp tortillas with chicken, peppers and melted cheese, with fresh tomato', 'dinner', 'chicken', '🧀', 25, 'balanced', 775, 53, 67, 32, 6, 10, 1358, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"cheese","amount":50,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp paprika","1/2 tsp ground cumin","salt"]'::jsonb, '["Cut the chicken into small pieces, season with the paprika, cumin and salt and fry in the oil for 6 minutes with the diced peppers","Cover one tortilla with half the grated cheese, the chicken and peppers and the rest of the cheese, then top with the second tortilla","Cook in a clean dry pan over medium heat for 3 minutes per side until golden and melted","Cut into wedges and serve with the diced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","hearty","chicken","tortilla","cheese","peppers","tomato","oil","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Кесадии с пилешко","description":"Хрупкави тортили с пилешко, чушки и разтопен кашкавал, с пресен домат","instructions":["Нарежете пилешкото на малки парчета, овкусете го с червения пипер, кимиона и сол и го запържете в олиото за 6 минути с нарязаните на кубчета чушки","Покрийте едната тортила с половината настърган кашкавал, пилешкото с чушките и останалия кашкавал и сложете отгоре втората тортила","Печете в чист сух тиган на среден огън по 3 минути от всяка страна, докато стане златиста и кашкавалът се разтопи","Нарежете на триъгълници и поднесете с нарязания на кубчета домат"],"seasonings":["1 ч.л. червен пипер","1/2 ч.л. смлян кимион","сол"]},"nl":{"name":"Quesadilla''s met kip","description":"Knapperige tortilla''s met kip, paprika en gesmolten kaas, met verse tomaat","instructions":["Snijd de kip in kleine stukjes, kruid ze met het paprikapoeder, de komijn en zout en bak ze 6 minuten in de olie met de blokjes paprika","Beleg één tortilla met de helft van de geraspte kaas, de kip met paprika en de rest van de kaas en leg de tweede tortilla erop","Bak in een schone droge pan op middelhoog vuur 3 minuten per kant, tot hij goudbruin is en de kaas gesmolten is","Snijd in punten en serveer met de tomatenblokjes"],"seasonings":["1 tl paprikapoeder","1/2 tl gemalen komijn","zout"]}}'::jsonb, 84),
  ('d-beef-burrito-salad-bowl', 'Beef Burrito Salad Bowl', 'Seared beef over lettuce with rice, beans, corn, tomato and avocado', 'dinner', 'beef', '🥗', 25, 'balanced', 782, 48, 76, 34, 18, 10, 415, '[{"name":"beef","amount":150,"unit":"g"},{"name":"lettuce","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"rice","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it cool a little","Rub the beef with the cumin, paprika and salt and sear it in the oil over high heat for 2 to 3 minutes per side, then rest it for 3 minutes and slice thinly","Shred the lettuce and dice the tomato and avocado","Build the bowl with the lettuce, rice, drained kidney beans, corn, tomato and avocado, top with the beef and squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","fresh","hearty","beef","lettuce","tomato","corn","kidney beans","avocado","rice","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бурито салата с телешко","description":"Запечатано телешко върху маруля с ориз, боб, царевица, домат и авокадо","instructions":["Сварете ориза в подсолена вода за 10–12 минути, отцедете го и го оставете леко да изстине","Натрийте телешкото с кимиона, червения пипер и сол и го запечатайте в олиото на силен огън по 2–3 минути от всяка страна, след което го оставете да почине 3 минути и го нарежете на тънко","Нарежете марулята на ивици, а домата и авокадото на кубчета","Подредете купата с марулята, ориза, отцедения червен боб, царевицата, домата и авокадото, сложете телешкото отгоре и изстискайте сок от лайм"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол","няколко капки сок от лайм"]},"nl":{"name":"Burrito-saladebowl met rundvlees","description":"Kort gebakken rundvlees op sla met rijst, bonen, mais, tomaat en avocado","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, giet af en laat hem iets afkoelen","Wrijf het rundvlees in met de komijn, het paprikapoeder en zout en schroei het in de olie op hoog vuur 2 tot 3 minuten per kant dicht; laat 3 minuten rusten en snijd in dunne plakjes","Snijd de sla in reepjes en de tomaat en de avocado in blokjes","Bouw de kom op met de sla, de rijst, de uitgelekte kidneybonen, de mais, de tomaat en de avocado, leg het vlees erop en knijp er limoensap over"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","zout","kneepje limoensap"]}}'::jsonb, 85),
  ('d-spaghetti-bolognese', 'Spaghetti Bolognese', 'Classic beef and tomato ragù with spaghetti and parmesan', 'dinner', 'beef mince', '🍝', 45, 'weekend', 829, 44, 87, 33, 9, 12, 483, '[{"name":"beef mince","amount":140,"unit":"g"},{"name":"pasta","amount":90,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"parmesan","amount":10,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 6 minutes","Add the beef mince and brown it well for 6 minutes, then stir in the chopped garlic and oregano","Add the chopped tomatoes, season and simmer gently for 25 minutes, adding a splash of water if it gets too thick","Cook the pasta in salted boiling water, drain, toss with the sauce and serve with the grated parmesan"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","hearty","beef mince","pasta","chopped tomatoes","onion","carrots","garlic","olive oil","parmesan","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Спагети болонезе","description":"Класическо рагу от телешка кайма и домати със спагети и пармезан","instructions":["Нарежете лука и морковите на ситни кубчета и ги задушете в зехтина за 6 минути","Добавете телешката кайма и я запържете добре за 6 минути, след което добавете накълцания чесън и ригана","Добавете нарязаните домати, овкусете и варете на тих огън 25 минути, като добавите малко вода, ако сосът стане твърде гъст","Сварете пастата в подсолена вряща вода, отцедете я, разбъркайте я със соса и поднесете с настъргания пармезан"],"seasonings":["1 ч.л. сух риган","сол","черен пипер"]},"nl":{"name":"Spaghetti bolognese","description":"Klassieke ragù van rundergehakt en tomaat met spaghetti en Parmezaanse kaas","instructions":["Snijd de ui en de wortels in kleine blokjes en bak ze 6 minuten zacht in de olijfolie","Voeg het rundergehakt toe en bak het 6 minuten goed bruin; roer dan de gehakte knoflook en de oregano erdoor","Voeg de tomatenblokjes toe, breng op smaak en laat 25 minuten zachtjes koken; voeg een scheutje water toe als de saus te dik wordt","Kook de pasta in kokend water met zout, giet af, meng met de saus en serveer met de geraspte Parmezaanse kaas"],"seasonings":["1 tl gedroogde oregano","zout","zwarte peper"]}}'::jsonb, 86),
  ('d-creamy-chicken-mushroom-pasta', 'Creamy Chicken and Mushroom Pasta', 'Pasta in a garlic cream sauce with chicken, mushrooms and parmesan', 'dinner', 'chicken', '🍄', 25, 'balanced', 769, 54, 73, 28, 4, 7, 254, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"pasta","amount":85,"unit":"g"},{"name":"mushrooms","amount":100,"unit":"g"},{"name":"cream sauce","amount":80,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"parmesan","amount":10,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a little of the water","Fry the chicken in strips in the oil over medium-high heat for 5 minutes, then add the sliced mushrooms for 4 minutes","Add the chopped garlic, then the cream sauce and a splash of pasta water and simmer for 2 minutes","Toss in the pasta and parmesan and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","hearty","chicken","pasta","mushrooms","cream sauce","garlic","parmesan","oil","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Кремообразна паста с пилешко и гъби","description":"Паста в сметанов сос с чесън, пилешко, гъби и пармезан","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката и я отцедете, като запазите малко от водата","Запържете пилешкото на ивици в олиото на умерено силен огън за 5 минути, след което добавете нарязаните гъби за 4 минути","Добавете накълцания чесън, след това сметановия сос и малко от водата от пастата и варете на тих огън 2 минути","Добавете пастата и пармезана, разбъркайте и овкусете с пипер"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Romige pasta met kip en champignons","description":"Pasta in een roomsaus met knoflook, kip, champignons en Parmezaanse kaas","instructions":["Kook de pasta in kokend water met zout volgens de verpakking en giet af; bewaar een beetje kookvocht","Bak de kip in reepjes 5 minuten in de olie op middelhoog tot hoog vuur en bak dan de plakjes champignon 4 minuten mee","Voeg de gehakte knoflook toe, dan de roomsaus en een scheutje kookvocht, en laat 2 minuten zachtjes koken","Schep de pasta en de Parmezaanse kaas erdoor en breng op smaak met peper"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 87),
  ('d-pesto-salmon-potatoes', 'Pesto Salmon with Potatoes and Green Beans', 'Baked salmon with a pesto crust, boiled potatoes and green beans', 'dinner', 'salmon', '🐟', 30, 'balanced', 627, 39, 53, 29, 9, 6, 310, '[{"name":"salmon","amount":150,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"pesto","amount":20,"unit":"g"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Heat the oven to 200°C and boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the green beans for the last 5","Put the salmon on a lined tray, spread the pesto over the top and bake for 12 minutes","Drain the potatoes and beans and season them","Serve with the salmon and a squeeze of lemon"]'::jsonb, '["stovetop","oven"]'::jsonb, '["italian","light","salmon","potatoes","green beans","pesto","stovetop","oven","dinner"]'::jsonb, '["gluten-free","halal","kosher"]'::jsonb, '{"bg":{"name":"Сьомга с песто, картофи и зелен фасул","description":"Печена сьомга с коричка от песто, варени картофи и зелен фасул","instructions":["Загрейте фурната на 200°C и сварете картофите, нарязани на парчета, в подсолена вода за 15 минути, като през последните 5 добавите зеления фасул","Сложете сьомгата в тава с хартия за печене, намажете я отгоре с пестото и печете 12 минути","Отцедете картофите и фасула и ги овкусете","Поднесете със сьомгата и няколко капки лимон"],"seasonings":["сол","черен пипер","няколко капки лимонов сок"]},"nl":{"name":"Pestozalm met aardappelen en sperziebonen","description":"Zalm uit de oven met een pestokorstje, gekookte aardappelen en sperziebonen","instructions":["Verwarm de oven voor op 200°C en kook de aardappelen, in stukken gesneden, 15 minuten in water met zout; kook de sperziebonen de laatste 5 minuten mee","Leg de zalm op een met bakpapier beklede bakplaat, smeer de pesto erover en bak 12 minuten","Giet de aardappelen en de bonen af en breng ze op smaak","Serveer met de zalm en een kneepje citroen"],"seasonings":["zout","zwarte peper","kneepje citroensap"]}}'::jsonb, 88),
  ('d-pork-ragu-penne', 'Pork Ragù with Penne', 'Rich pork mince and tomato sauce with penne', 'dinner', 'pork mince', '🍝', 40, 'balanced', 782, 36, 82, 34, 9, 11, 339, '[{"name":"pork mince","amount":130,"unit":"g"},{"name":"pasta","amount":85,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"carrots","amount":40,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","pinch of fennel seeds","salt","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 5 minutes","Add the pork mince and brown it for 6 minutes, then add the chopped garlic, oregano and fennel seeds","Add the chopped tomatoes and simmer for 20 minutes","Cook the pasta in salted boiling water, drain and toss with the ragù"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","hearty","pork mince","pasta","chopped tomatoes","onion","carrots","garlic","olive oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Пене със свинско рагу","description":"Плътен сос от свинска кайма и домати с пене","instructions":["Нарежете лука и морковите на ситни кубчета и ги задушете в зехтина за 5 минути","Добавете свинската кайма и я запържете 6 минути, след което добавете накълцания чесън, ригана и семената от резене","Добавете нарязаните домати и варете на тих огън 20 минути","Сварете пастата в подсолена вряща вода, отцедете я и я разбъркайте с рагуто"],"seasonings":["1 ч.л. сух риган","щипка семена от резене","сол","черен пипер"]},"nl":{"name":"Penne met varkensragù","description":"Volle saus van varkensgehakt en tomaat met penne","instructions":["Snijd de ui en de wortels in kleine blokjes en bak ze 5 minuten zacht in de olijfolie","Voeg het varkensgehakt toe en bak het 6 minuten bruin; voeg dan de gehakte knoflook, de oregano en het venkelzaad toe","Voeg de tomatenblokjes toe en laat 20 minuten zachtjes koken","Kook de pasta in kokend water met zout, giet af en meng met de ragù"],"seasonings":["1 tl gedroogde oregano","snufje venkelzaad","zout","zwarte peper"]}}'::jsonb, 89),
  ('d-lentil-bolognese', 'Lentil Bolognese', 'Hearty vegan lentil and tomato sauce with pasta', 'dinner', 'lentils', '🍝', 40, 'balanced', 738, 32, 127, 13, 17, 14, 284, '[{"name":"lentils","amount":75,"unit":"g"},{"name":"pasta","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","{300} ml water","salt","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 5 minutes, then add the chopped garlic and oregano","Add the rinsed lentils, chopped tomatoes and water and simmer for 25 minutes until the lentils are tender and the sauce is thick","Cook the pasta in salted boiling water and drain","Season the sauce and serve over the pasta"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","lentils","pasta","chopped tomatoes","carrots","onion","garlic","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Болонезе с леща","description":"Засищащ веган сос от леща и домати с паста","instructions":["Нарежете лука и морковите на ситни кубчета и ги задушете в зехтина за 5 минути, след което добавете накълцания чесън и ригана","Добавете измитата леща, нарязаните домати и водата и варете на тих огън 25 минути, докато лещата омекне и сосът се сгъсти","Сварете пастата в подсолена вряща вода и я отцедете","Овкусете соса и го поднесете върху пастата"],"seasonings":["1 ч.л. сух риган","{300} мл вода","сол","черен пипер"]},"nl":{"name":"Linzenbolognese","description":"Stevige vegan saus van linzen en tomaat met pasta","instructions":["Snijd de ui en de wortels in kleine blokjes en bak ze 5 minuten zacht in de olijfolie; voeg dan de gehakte knoflook en de oregano toe","Voeg de afgespoelde linzen, de tomatenblokjes en het water toe en laat 25 minuten zachtjes koken tot de linzen gaar zijn en de saus dik is","Kook de pasta in kokend water met zout en giet af","Breng de saus op smaak en serveer op de pasta"],"seasonings":["1 tl gedroogde oregano","{300} ml water","zout","zwarte peper"]}}'::jsonb, 90),
  ('d-chicken-parmesan-bake', 'Chicken Parmesan Bake', 'Chicken baked in tomato sauce under mozzarella and parmesan, with pasta', 'dinner', 'chicken', '🧀', 40, 'balanced', 800, 66, 67, 29, 5, 9, 542, '[{"name":"chicken","amount":170,"unit":"g"},{"name":"tomato sauce","amount":150,"unit":"g"},{"name":"mozzarella","amount":50,"unit":"g"},{"name":"parmesan","amount":15,"unit":"g"},{"name":"pasta","amount":70,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Heat the oven to 200°C, season the chicken and brown it in the olive oil for 2 minutes per side","Put it in a small baking dish, pour over the tomato sauce mixed with the oregano and top with the sliced mozzarella and grated parmesan","Bake for 20 minutes until the chicken is cooked through and the cheese is golden","Meanwhile cook the pasta in salted boiling water, drain and serve with the chicken and its sauce"]'::jsonb, '["stovetop","oven"]'::jsonb, '["italian","comfort","hearty","chicken","tomato sauce","mozzarella","parmesan","pasta","olive oil","stovetop","oven","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Пилешко „Пармиджана“ на фурна","description":"Пилешко, запечено в доматен сос под моцарела и пармезан, с паста","instructions":["Загрейте фурната на 200°C, овкусете пилешкото и го запържете в зехтина по 2 минути от всяка страна","Сложете го в малка тава, залейте го с доматения сос, смесен с ригана, и наредете отгоре нарязаната моцарела и настъргания пармезан","Печете 20 минути, докато пилешкото се сготви и сиренето стане златисто","Междувременно сварете пастата в подсолена вряща вода, отцедете я и я поднесете с пилешкото и соса"],"seasonings":["1 ч.л. сух риган","сол","черен пипер"]},"nl":{"name":"Kip parmigiana uit de oven","description":"Kip gebakken in tomatensaus onder mozzarella en Parmezaanse kaas, met pasta","instructions":["Verwarm de oven voor op 200°C, kruid de kip en bak hem 2 minuten per kant bruin in de olijfolie","Leg hem in een kleine ovenschaal, giet de tomatensaus gemengd met de oregano erover en beleg met de plakjes mozzarella en de geraspte Parmezaanse kaas","Bak 20 minuten tot de kip gaar is en de kaas goudbruin","Kook intussen de pasta in kokend water met zout, giet af en serveer met de kip en de saus"],"seasonings":["1 tl gedroogde oregano","zout","zwarte peper"]}}'::jsonb, 91),
  ('d-shrimp-arrabbiata', 'Shrimp Arrabbiata', 'Spaghetti with shrimp in a spicy garlic tomato sauce', 'dinner', 'shrimp', '🌶️', 20, 'quick', 626, 46, 78, 15, 7, 8, 428, '[{"name":"shrimp","amount":160,"unit":"g"},{"name":"pasta","amount":90,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp chili flakes","salt","handful of fresh parsley"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain","Gently fry the sliced garlic and chili flakes in the olive oil for 1 minute","Add the chopped tomatoes and simmer for 8 minutes","Add the shrimp and cook for 3 minutes until pink, then toss with the pasta and parsley"]'::jsonb, '["stovetop"]'::jsonb, '["italian","spicy","quick","light","shrimp","pasta","chopped tomatoes","garlic","olive oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Скариди „Арабиата“","description":"Спагети със скариди в пикантен доматен сос с чесън","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката и я отцедете","Запържете леко нарязания чесън и люспите чили в зехтина за 1 минута","Добавете нарязаните домати и варете на тих огън 8 минути","Добавете скаридите и гответе 3 минути, докато порозовеят, след което разбъркайте с пастата и магданоза"],"seasonings":["1 ч.л. люспи чили","сол","шепа пресен магданоз"]},"nl":{"name":"Garnalen all''arrabbiata","description":"Spaghetti met garnalen in een pittige tomatensaus met knoflook","instructions":["Kook de pasta in kokend water met zout volgens de verpakking en giet af","Bak de plakjes knoflook en de chilivlokken 1 minuut zachtjes in de olijfolie","Voeg de tomatenblokjes toe en laat 8 minuten zachtjes koken","Voeg de garnalen toe en bak 3 minuten tot ze roze zijn; meng dan met de pasta en de peterselie"],"seasonings":["1 tl chilivlokken","zout","handje verse peterselie"]}}'::jsonb, 92),
  ('d-chicken-mushroom-risotto', 'Chicken and Mushroom Risotto', 'Creamy rice with chicken, mushrooms, peas and parmesan', 'dinner', 'chicken', '🍚', 40, 'balanced', 747, 51, 92, 19, 6, 8, 492, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"rice","amount":90,"unit":"g"},{"name":"mushrooms","amount":150,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"parmesan","amount":25,"unit":"g"},{"name":"butter","amount":10,"unit":"g"},{"name":"peas","amount":60,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"}]'::jsonb, '["1 stock cube","{600} ml hot water","black pepper"]'::jsonb, '["Melt half the butter in a wide pan and cook the chicken in small pieces with the diced onion and sliced mushrooms for 6 minutes","Add the chopped garlic and rice and stir for 1 minute","Dissolve the stock cube in the hot water and add it a ladle at a time, stirring often, for about 20 minutes until the rice is creamy and just tender","Stir in the peas for the last 3 minutes, then the remaining butter and the grated parmesan, and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","chicken","rice","mushrooms","onion","parmesan","butter","peas","garlic","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Ризото с пилешко и гъби","description":"Кремообразен ориз с пилешко, гъби, грах и пармезан","instructions":["Разтопете половината масло в широк тиган и гответе пилешкото на малки парчета с нарязания на кубчета лук и нарязаните гъби за 6 минути","Добавете накълцания чесън и ориза и бъркайте 1 минута","Разтворете кубчето бульон в горещата вода и я добавяйте по един черпак, като бъркате често, около 20 минути, докато оризът стане кремообразен и едва омекне","Добавете граха през последните 3 минути, след това останалото масло и настъргания пармезан и овкусете с пипер"],"seasonings":["1 кубче бульон","{600} мл гореща вода","черен пипер"]},"nl":{"name":"Risotto met kip en champignons","description":"Romige rijst met kip, champignons, doperwten en Parmezaanse kaas","instructions":["Smelt de helft van de boter in een brede pan en bak de kip in kleine stukjes 6 minuten met de blokjes ui en de plakjes champignon","Voeg de gehakte knoflook en de rijst toe en roer 1 minuut","Los het bouillonblokje op in het hete water en voeg het lepel voor lepel toe; roer vaak, ongeveer 20 minuten, tot de rijst romig en net gaar is","Roer de laatste 3 minuten de doperwten erdoor, dan de rest van de boter en de geraspte Parmezaanse kaas, en breng op smaak met peper"],"seasonings":["1 bouillonblokje","{600} ml heet water","zwarte peper"]}}'::jsonb, 93),
  ('d-eggs-in-purgatory', 'Eggs in Purgatory', 'Eggs baked in a spicy garlic tomato sauce, with bread for dipping', 'dinner', 'eggs', '🍅', 20, 'quick', 611, 37, 43, 32, 9, 10, 1018, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"chopped tomatoes","amount":250,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"parmesan","amount":15,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","salt","pinch of dried oregano"]'::jsonb, '["Gently fry the sliced garlic and chili flakes in the olive oil for 1 minute","Add the chopped tomatoes, oregano and salt and simmer for 8 minutes until thickened","Make {n:eggs} wells, crack in the eggs, cover and cook for 4 to 5 minutes until the whites are set","Scatter with the grated parmesan and serve with the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["italian","spicy","quick","light","eggs","chopped tomatoes","garlic","parmesan","bread","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Яйца в чистилището","description":"Яйца, сготвени в пикантен доматен сос с чесън, с хляб за топене","instructions":["Запържете леко нарязания чесън и люспите чили в зехтина за 1 минута","Добавете нарязаните домати, ригана и сол и варете на тих огън 8 минути, докато сосът се сгъсти","Направете {n:eggs} гнезда, чукнете яйцата в тях, покрийте и гответе 4–5 минути, докато белтъкът стегне","Поръсете с настъргания пармезан и поднесете с препечения хляб"],"seasonings":["1/2 ч.л. люспи чили","сол","щипка сух риган"]},"nl":{"name":"Eieren in het vagevuur","description":"Eieren gegaard in een pittige tomatensaus met knoflook, met brood om te dippen","instructions":["Bak de plakjes knoflook en de chilivlokken 1 minuut zachtjes in de olijfolie","Voeg de tomatenblokjes, de oregano en zout toe en laat 8 minuten zachtjes koken tot de saus dikker is","Maak {n:eggs} kuiltjes, breek de eieren erin, dek af en laat 4 tot 5 minuten garen tot het eiwit gestold is","Bestrooi met de geraspte Parmezaanse kaas en serveer met het geroosterde brood"],"seasonings":["1/2 tl chilivlokken","zout","snufje gedroogde oregano"]}}'::jsonb, 94),
  ('d-turkey-meatballs-pasta', 'Turkey Meatballs in Tomato Sauce', 'Tender turkey meatballs simmered in tomato sauce, with pasta and parmesan', 'dinner', 'turkey mince', '🍝', 35, 'balanced', 734, 49, 81, 24, 7, 13, 268, '[{"name":"turkey mince","amount":160,"unit":"g"},{"name":"pasta","amount":80,"unit":"g"},{"name":"tomato sauce","amount":180,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"},{"name":"parmesan","amount":10,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Mix the turkey mince with the finely chopped garlic, half the oregano, salt and pepper and roll into {8} small balls","Brown the meatballs in the olive oil for 5 minutes, then add the diced onion for 2 minutes","Pour in the tomato sauce with the remaining oregano and simmer, covered, for 12 minutes","Cook the pasta in salted boiling water, drain and serve with the meatballs, sauce and grated parmesan"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","turkey mince","pasta","tomato sauce","onion","garlic","parmesan","olive oil","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Пуешки кюфтенца в доматен сос","description":"Крехки кюфтенца от пуешка кайма, задушени в доматен сос, с паста и пармезан","instructions":["Смесете пуешката кайма със ситно накълцания чесън, половината риган, сол и пипер и оформете {8} малки топчета","Запържете кюфтенцата в зехтина за 5 минути, след което добавете нарязания на кубчета лук за 2 минути","Изсипете доматения сос с останалия риган и варете под капак на тих огън 12 минути","Сварете пастата в подсолена вряща вода, отцедете я и я поднесете с кюфтенцата, соса и настъргания пармезан"],"seasonings":["1 ч.л. сух риган","сол","черен пипер"]},"nl":{"name":"Kalkoenballetjes in tomatensaus","description":"Malse balletjes van kalkoengehakt gestoofd in tomatensaus, met pasta en Parmezaanse kaas","instructions":["Meng het kalkoengehakt met de fijngehakte knoflook, de helft van de oregano, zout en peper en rol er {8} kleine balletjes van","Bak de balletjes 5 minuten bruin in de olijfolie en bak dan de blokjes ui 2 minuten mee","Giet de tomatensaus met de rest van de oregano erbij en laat 12 minuten met het deksel op de pan zachtjes koken","Kook de pasta in kokend water met zout, giet af en serveer met de balletjes, de saus en de geraspte Parmezaanse kaas"],"seasonings":["1 tl gedroogde oregano","zout","zwarte peper"]}}'::jsonb, 95),
  ('d-tuna-pasta-bake', 'Tuna Pasta Bake', 'Creamy baked pasta with tuna, corn and peas under a cheese crust', 'dinner', 'tuna', '🧀', 35, 'balanced', 753, 48, 81, 27, 6, 11, 761, '[{"name":"tuna","amount":120,"unit":"g"},{"name":"pasta","amount":85,"unit":"g"},{"name":"cream sauce","amount":80,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Heat the oven to 200°C and cook the pasta in salted boiling water for 2 minutes less than the packet says, then drain","Mix the pasta with the drained tuna, cream sauce, corn and peas and season","Tip into a small baking dish and scatter over the grated cheese","Bake for 15 minutes until golden and bubbling"]'::jsonb, '["stovetop","oven"]'::jsonb, '["italian","comfort","hearty","tuna","pasta","cream sauce","corn","peas","cheese","stovetop","oven","dinner"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Запечена паста с риба тон","description":"Кремообразна запечена паста с риба тон, царевица и грах под коричка от кашкавал","instructions":["Загрейте фурната на 200°C и сварете пастата в подсолена вряща вода 2 минути по-малко от указаното на опаковката, след което я отцедете","Смесете пастата с отцедената риба тон, сметановия сос, царевицата и граха и овкусете","Изсипете в малка тава и поръсете с настъргания кашкавал","Печете 15 минути, докато стане златиста и започне да къкри"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Pastaschotel met tonijn","description":"Romige pasta uit de oven met tonijn, mais en doperwten onder een kaaskorst","instructions":["Verwarm de oven voor op 200°C en kook de pasta in kokend water met zout 2 minuten korter dan op de verpakking staat; giet af","Meng de pasta met de uitgelekte tonijn, de roomsaus, de mais en de doperwten en breng op smaak","Schep in een kleine ovenschaal en bestrooi met de geraspte kaas","Bak 15 minuten tot de schotel goudbruin is en bubbelt"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 96),
  ('d-chickpea-spinach-pasta', 'Chickpea and Spinach Pasta', 'Garlicky tomato pasta with chickpeas and wilted spinach', 'dinner', 'chickpeas', '🍝', 20, 'quick', 631, 24, 102, 16, 16, 12, 578, '[{"name":"chickpeas","amount":130,"unit":"g"},{"name":"pasta","amount":80,"unit":"g"},{"name":"spinach","amount":100,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["pinch of dried oregano","salt","black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain","Gently fry the sliced garlic in the olive oil for 1 minute, then add the chopped tomatoes, drained chickpeas and oregano","Simmer for 8 minutes, then stir in the spinach until wilted","Toss with the pasta and season"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","light","chickpeas","pasta","spinach","chopped tomatoes","garlic","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Паста с нахут и спанак","description":"Паста в доматен сос с чесън, нахут и задушен спанак","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката и я отцедете","Запържете леко нарязания чесън в зехтина за 1 минута, след което добавете нарязаните домати, отцедения нахут и ригана","Варете на тих огън 8 минути, след което добавете спанака и бъркайте, докато омекне","Разбъркайте с пастата и овкусете"],"seasonings":["щипка сух риган","сол","черен пипер"]},"nl":{"name":"Pasta met kikkererwten en spinazie","description":"Tomatenpasta met knoflook, kikkererwten en geslonken spinazie","instructions":["Kook de pasta in kokend water met zout volgens de verpakking en giet af","Bak de plakjes knoflook 1 minuut zachtjes in de olijfolie en voeg dan de tomatenblokjes, de uitgelekte kikkererwten en de oregano toe","Laat 8 minuten zachtjes koken en roer dan de spinazie erdoor tot hij geslonken is","Meng met de pasta en breng op smaak"],"seasonings":["snufje gedroogde oregano","zout","zwarte peper"]}}'::jsonb, 97),
  ('d-greek-chicken-traybake', 'Greek Chicken Traybake', 'Chicken roasted with potatoes, zucchini, peppers and lemon, finished with feta', 'dinner', 'chicken', '🍋', 45, 'weekend', 679, 51, 68, 24, 11, 10, 450, '[{"name":"chicken","amount":170,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"zucchini","amount":120,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"feta","amount":30,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["2 tsp dried oregano","salt","black pepper"]'::jsonb, '["Heat the oven to 210°C","Cut the potatoes into small wedges and toss them on a tray with half the olive oil, salt and half the oregano, then roast for 15 minutes","Add the chicken, the zucchini and peppers in chunks, the remaining olive oil and oregano and the lemon cut into wedges","Roast for 20 more minutes until the chicken is cooked through, then crumble over the feta"]'::jsonb, '["oven"]'::jsonb, '["mediterranean","chicken","potatoes","zucchini","peppers","feta","olive oil","lemon","oven","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Пилешко по гръцки в тава","description":"Пилешко, печено с картофи, тиквичка, чушки и лимон, с фета отгоре","instructions":["Загрейте фурната на 210°C","Нарежете картофите на малки резени, разбъркайте ги в тава с половината зехтин, сол и половината риган и ги печете 15 минути","Добавете пилешкото, тиквичката и чушките на едри парчета, останалите зехтин и риган и лимона, нарязан на резени","Печете още 20 минути, докато пилешкото се сготви, и натрошете фетата отгоре"],"seasonings":["2 ч.л. сух риган","сол","черен пипер"]},"nl":{"name":"Griekse traybake met kip","description":"Kip geroosterd met aardappelen, courgette, paprika en citroen, afgemaakt met feta","instructions":["Verwarm de oven voor op 210°C","Snijd de aardappelen in kleine partjes, meng ze op een bakplaat met de helft van de olijfolie, zout en de helft van de oregano en rooster ze 15 minuten","Voeg de kip, de courgette en de paprika in stukken, de rest van de olijfolie en de oregano en de citroen in partjes toe","Rooster nog 20 minuten tot de kip gaar is en verkruimel de feta erover"],"seasonings":["2 tl gedroogde oregano","zout","zwarte peper"]}}'::jsonb, 98),
  ('d-baked-fish-tomato-potatoes', 'Baked Fish with Tomatoes and Potatoes', 'White fish baked on sliced potatoes with tomato, onion and garlic', 'dinner', 'white fish', '🐟', 40, 'balanced', 544, 40, 66, 14, 9, 8, 126, '[{"name":"white fish","amount":180,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"tomato","amount":150,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper","handful of fresh parsley"]'::jsonb, '["Heat the oven to 200°C","Slice the potatoes and onion thinly, toss with the olive oil, sliced garlic, salt and oregano and spread in a baking dish","Bake for 20 minutes until almost tender","Lay the sliced tomato and the fish on top, season and bake for 12 more minutes, then scatter with parsley"]'::jsonb, '["oven"]'::jsonb, '["mediterranean","light","white fish","potatoes","tomato","onion","garlic","olive oil","oven","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Печена риба с домати и картофи","description":"Бяла риба, печена върху резени картофи с домат, лук и чесън","instructions":["Загрейте фурната на 200°C","Нарежете картофите и лука на тънки резени, разбъркайте ги със зехтина, нарязания чесън, сол и ригана и ги разстелете в тава","Печете 20 минути, докато почти омекнат","Наредете отгоре нарязания домат и рибата, овкусете и печете още 12 минути, след което поръсете с магданоз"],"seasonings":["1 ч.л. сух риган","сол","черен пипер","шепа пресен магданоз"]},"nl":{"name":"Vis uit de oven met tomaat en aardappelen","description":"Witvis gebakken op plakjes aardappel met tomaat, ui en knoflook","instructions":["Verwarm de oven voor op 200°C","Snijd de aardappelen en de ui in dunne plakjes, meng ze met de olijfolie, de plakjes knoflook, zout en de oregano en verdeel ze over een ovenschaal","Bak 20 minuten tot ze bijna gaar zijn","Leg de plakjes tomaat en de vis erop, breng op smaak en bak nog 12 minuten; bestrooi dan met peterselie"],"seasonings":["1 tl gedroogde oregano","zout","zwarte peper","handje verse peterselie"]}}'::jsonb, 99),
  ('d-beef-kofta-couscous', 'Beef Kofta with Couscous', 'Spiced beef kofta with couscous, cucumber-tomato salad and yogurt', 'dinner', 'beef mince', '🍢', 25, 'balanced', 709, 41, 65, 31, 5, 8, 149, '[{"name":"beef mince","amount":150,"unit":"g"},{"name":"couscous","amount":70,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"yogurt","amount":80,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","{90} ml boiling water","salt"]'::jsonb, '["Mix the beef mince with the cumin, paprika, chili flakes and salt and shape into {4} short sausages","Fry them in the olive oil over medium-high heat for 8 to 10 minutes, turning, until cooked through","Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Serve the kofta on the couscous with the diced cucumber and tomato and the yogurt"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","beef mince","couscous","cucumber","tomato","yogurt","olive oil","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Телешка кофта с кускус","description":"Телешка кофта с подправки, кускус, салата от краставица и домат и кисело мляко","instructions":["Смесете телешката кайма с кимиона, червения пипер, люспите чили и сол и оформете {4} къси продълговати кюфтенца","Запържете ги в зехтина на умерено силен огън за 8–10 минути, като ги обръщате, докато се сготвят","Залейте кускуса с врящата вода и щипка сол, покрийте за 5 минути и го разрохкайте с вилица","Поднесете кофтата върху кускуса с нарязаните на кубчета краставица и домат и киселото мляко"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","1/2 ч.л. люспи чили","{90} мл вряща вода","сол"]},"nl":{"name":"Runderkofta met couscous","description":"Gekruide runderkofta met couscous, een salade van komkommer en tomaat en yoghurt","instructions":["Meng het rundergehakt met de komijn, het paprikapoeder, de chilivlokken en zout en vorm er {4} korte worstjes van","Bak ze 8 tot 10 minuten in de olijfolie op middelhoog tot hoog vuur gaar; keer regelmatig","Giet het kokende water over de couscous met een snufje zout, dek 5 minuten af en maak los met een vork","Serveer de kofta op de couscous met de blokjes komkommer en tomaat en de yoghurt"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","1/2 tl chilivlokken","{90} ml kokend water","zout"]}}'::jsonb, 100),
  ('d-spanish-chickpea-spinach-stew', 'Spanish Chickpea and Spinach Stew', 'Garlicky chickpeas and spinach in a smoky tomato sauce, with bread', 'dinner', 'chickpeas', '🥘', 25, 'balanced', 569, 25, 79, 20, 22, 16, 947, '[{"name":"chickpeas","amount":200,"unit":"g"},{"name":"spinach","amount":150,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"olive oil","amount":12,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["1 tsp smoked paprika","1/2 tsp ground cumin","1/2 tsp chili flakes","salt"]'::jsonb, '["Dice the onion and soften it in the olive oil for 4 minutes, then add the sliced garlic, paprika, cumin and chili flakes for 1 minute","Add the chopped tomatoes and drained chickpeas and simmer for 10 minutes","Stir in the spinach a handful at a time until it wilts and season with salt","Serve with the bread"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","comfort","light","chickpeas","spinach","chopped tomatoes","onion","garlic","olive oil","bread","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Испанска яхния с нахут и спанак","description":"Нахут и спанак с чесън в доматен сос с пушен пипер, с хляб","instructions":["Нарежете лука на кубчета и го задушете в зехтина за 4 минути, след което добавете нарязания чесън, червения пипер, кимиона и люспите чили за 1 минута","Добавете нарязаните домати и отцедения нахут и варете на тих огън 10 минути","Добавяйте спанака шепа по шепа, докато омекне, и овкусете със сол","Поднесете с хляба"],"seasonings":["1 ч.л. пушен червен пипер","1/2 ч.л. смлян кимион","1/2 ч.л. люспи чили","сол"]},"nl":{"name":"Spaanse stoof van kikkererwten en spinazie","description":"Kikkererwten en spinazie met knoflook in een rokerige tomatensaus, met brood","instructions":["Snijd de ui in blokjes en bak hem 4 minuten zacht in de olijfolie; voeg dan de plakjes knoflook, het paprikapoeder, de komijn en de chilivlokken 1 minuut toe","Voeg de tomatenblokjes en de uitgelekte kikkererwten toe en laat 10 minuten zachtjes koken","Roer de spinazie er handje voor handje door tot hij slinkt en breng op smaak met zout","Serveer met het brood"],"seasonings":["1 tl gerookt paprikapoeder","1/2 tl gemalen komijn","1/2 tl chilivlokken","zout"]}}'::jsonb, 101),
  ('d-lemon-herb-salmon-couscous', 'Lemon Herb Salmon with Couscous', 'Pan-fried salmon with lemon couscous and green beans', 'dinner', 'salmon', '🐟', 20, 'quick', 682, 42, 64, 29, 8, 5, 104, '[{"name":"salmon","amount":150,"unit":"g"},{"name":"couscous","amount":65,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp dried oregano","{85} ml boiling water","salt","black pepper"]'::jsonb, '["Boil the green beans in salted water for 5 minutes and drain","Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes, then fluff and stir in half the juice of the lemon","Season the salmon with the oregano, salt and pepper and fry in the olive oil for 3 to 4 minutes per side","Serve the salmon on the couscous with the beans and the rest of the lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","salmon","couscous","green beans","olive oil","lemon","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Сьомга с лимон и билки и кускус","description":"Сьомга на тиган с лимонов кускус и зелен фасул","instructions":["Сварете зеления фасул в подсолена вода за 5 минути и го отцедете","Залейте кускуса с врящата вода и щипка сол, покрийте за 5 минути, след което го разрохкайте и добавете половината от сока от лимона","Овкусете сьомгата с ригана, сол и пипер и я изпържете в зехтина по 3–4 минути от всяка страна","Поднесете сьомгата върху кускуса с фасула и останалия лимонов сок"],"seasonings":["1 ч.л. сух риган","{85} мл вряща вода","сол","черен пипер"]},"nl":{"name":"Zalm met citroen en kruiden en couscous","description":"Gebakken zalm met citroencouscous en sperziebonen","instructions":["Kook de sperziebonen 5 minuten in water met zout en giet af","Giet het kokende water over de couscous met een snufje zout, dek 5 minuten af, maak los en roer de helft van het sap van de citroen erdoor","Kruid de zalm met de oregano, zout en peper en bak hem 3 tot 4 minuten per kant in de olijfolie","Serveer de zalm op de couscous met de bonen en de rest van het citroensap"],"seasonings":["1 tl gedroogde oregano","{85} ml kokend water","zout","zwarte peper"]}}'::jsonb, 102),
  ('d-harissa-chicken-chickpeas', 'Harissa Chicken with Chickpeas and Couscous', 'Spicy chicken with peppers and chickpeas over couscous', 'dinner', 'chicken', '🌶️', 30, 'balanced', 775, 54, 93, 20, 13, 9, 331, '[{"name":"chicken","amount":160,"unit":"g"},{"name":"chickpeas","amount":100,"unit":"g"},{"name":"couscous","amount":80,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1 tbsp harissa paste","{100} ml boiling water","salt","squeeze of lemon juice"]'::jsonb, '["Coat the chicken, cut into chunks, with the harissa and a pinch of salt","Fry the sliced onion and peppers in the olive oil for 4 minutes, add the chicken and cook for 7 minutes until browned and cooked through","Add the drained chickpeas and warm through for 2 minutes","Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes, fluff and serve under the chicken with lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","hearty","chicken","chickpeas","couscous","peppers","onion","olive oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пилешко с хариса, нахут и кускус","description":"Пикантно пилешко с чушки и нахут върху кускус","instructions":["Овалвайте пилешкото, нарязано на парчета, в харисата и щипка сол","Запържете нарязаните лук и чушки в зехтина за 4 минути, добавете пилешкото и гответе 7 минути, докато се зачерви и се сготви","Добавете отцедения нахут и затоплете 2 минути","Залейте кускуса с врящата вода и щипка сол, покрийте за 5 минути, разрохкайте го и го поднесете под пилешкото с лимонов сок"],"seasonings":["1 с.л. хариса","{100} мл вряща вода","сол","няколко капки лимонов сок"]},"nl":{"name":"Harissakip met kikkererwten en couscous","description":"Pittige kip met paprika en kikkererwten op couscous","instructions":["Wentel de kip, in stukken gesneden, door de harissa en een snufje zout","Bak de reepjes ui en paprika 4 minuten in de olijfolie, voeg de kip toe en bak 7 minuten bruin en gaar","Voeg de uitgelekte kikkererwten toe en verwarm 2 minuten mee","Giet het kokende water over de couscous met een snufje zout, dek 5 minuten af, maak los en serveer onder de kip met citroensap"],"seasonings":["1 el harissa","{100} ml kokend water","zout","kneepje citroensap"]}}'::jsonb, 103),
  ('d-stuffed-peppers-feta', 'Rice-Stuffed Peppers with Feta', 'Peppers filled with rice, chickpeas and feta, baked in tomato sauce', 'dinner', 'chickpeas', '🫑', 55, 'weekend', 722, 23, 103, 26, 14, 22, 877, '[{"name":"peppers","amount":300,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"chickpeas","amount":60,"unit":"g"},{"name":"feta","amount":60,"unit":"g"},{"name":"tomato sauce","amount":100,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Heat the oven to 200°C and boil the rice in salted water for 10 minutes, then drain","Soften the diced onion in the olive oil for 4 minutes and mix it with the rice, drained chickpeas, crumbled feta, oregano and half the tomato sauce","Halve the peppers lengthways and scoop out the seeds. Fill the pepper halves with the mixture","Stand them in a baking dish, spoon over the remaining tomato sauce, cover with foil and bake for 35 minutes"]'::jsonb, '["stovetop","oven"]'::jsonb, '["mediterranean","comfort","peppers","rice","chickpeas","feta","tomato sauce","onion","olive oil","stovetop","oven","dinner"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Чушки, пълнени с ориз и фета","description":"Чушки, пълнени с ориз, нахут и фета и запечени в доматен сос","instructions":["Загрейте фурната на 200°C и сварете ориза в подсолена вода за 10 минути, след което го отцедете","Задушете нарязания на кубчета лук в зехтина за 4 минути и го смесете с ориза, отцедения нахут, натрошената фета, ригана и половината доматен сос","Разрежете чушките по дължина и извадете семките. Напълнете половинките със сместа","Наредете ги в тава, полейте с останалия доматен сос, покрийте с фолио и печете 35 минути"],"seasonings":["1 ч.л. сух риган","сол","черен пипер"]},"nl":{"name":"Paprika''s gevuld met rijst en feta","description":"Paprika''s gevuld met rijst, kikkererwten en feta, gebakken in tomatensaus","instructions":["Verwarm de oven voor op 200°C en kook de rijst 10 minuten in water met zout; giet af","Bak de blokjes ui 4 minuten zacht in de olijfolie en meng ze met de rijst, de uitgelekte kikkererwten, de verkruimelde feta, de oregano en de helft van de tomatensaus","Halveer de paprika''s in de lengte en verwijder de zaadjes. Vul de halve paprika''s met het mengsel","Zet ze in een ovenschaal, schep de rest van de tomatensaus erover, dek af met aluminiumfolie en bak 35 minuten"],"seasonings":["1 tl gedroogde oregano","zout","zwarte peper"]}}'::jsonb, 104),
  ('d-pork-souvlaki-potatoes', 'Pork Souvlaki with Potatoes and Tzatziki', 'Oregano pork with roast potatoes and a cucumber garlic yogurt', 'dinner', 'pork', '🍢', 40, 'balanced', 679, 49, 65, 26, 8, 9, 133, '[{"name":"pork","amount":160,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"greek yogurt","amount":80,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"},{"name":"olive oil","amount":12,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["2 tsp dried oregano","salt","black pepper"]'::jsonb, '["Heat the oven to 210°C, cut the potatoes into wedges, toss with half the olive oil and salt and roast for 30 minutes","Cut the pork into chunks and toss with the remaining olive oil, oregano, half the juice of the lemon, salt and pepper","Grate the cucumber, squeeze out the water and mix it with the yogurt, finely grated garlic and a pinch of salt","Fry the pork over high heat for 6 to 8 minutes until browned and serve with the potatoes, tzatziki and remaining lemon"]'::jsonb, '["stovetop","oven"]'::jsonb, '["mediterranean","pork","potatoes","greek yogurt","cucumber","garlic","olive oil","lemon","stovetop","oven","dinner"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Свински сувлаки с картофи и дзадзики","description":"Свинско с риган, печени картофи и кисело мляко с краставица и чесън","instructions":["Загрейте фурната на 210°C, нарежете картофите на резени, разбъркайте ги с половината зехтин и сол и ги печете 30 минути","Нарежете свинското на парчета и го разбъркайте с останалия зехтин, ригана, половината от сока от лимона, сол и пипер","Настържете краставицата, изстискайте водата и я смесете с киселото мляко, ситно настъргания чесън и щипка сол","Запържете свинското на силен огън за 6–8 минути, докато се зачерви, и поднесете с картофите, дзадзикито и останалия лимон"],"seasonings":["2 ч.л. сух риган","сол","черен пипер"]},"nl":{"name":"Varkenssouvlaki met aardappelen en tzatziki","description":"Varkensvlees met oregano, geroosterde aardappelen en yoghurt met komkommer en knoflook","instructions":["Verwarm de oven voor op 210°C, snijd de aardappelen in partjes, meng ze met de helft van de olijfolie en zout en rooster ze 30 minuten","Snijd het varkensvlees in stukken en meng ze met de rest van de olijfolie, de oregano, de helft van het sap van de citroen, zout en peper","Rasp de komkommer, knijp het vocht eruit en meng hem met de yoghurt, de fijn geraspte knoflook en een snufje zout","Bak het vlees 6 tot 8 minuten op hoog vuur bruin en serveer met de aardappelen, de tzatziki en de rest van de citroen"],"seasonings":["2 tl gedroogde oregano","zout","zwarte peper"]}}'::jsonb, 105),
  ('d-shrimp-tomato-feta', 'Shrimp with Tomato and Feta', 'Shrimp simmered in a garlic tomato sauce with feta, served with rice', 'dinner', 'shrimp', '🍤', 25, 'balanced', 693, 49, 74, 23, 7, 9, 1066, '[{"name":"shrimp","amount":170,"unit":"g"},{"name":"chopped tomatoes","amount":250,"unit":"g"},{"name":"feta","amount":50,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"rice","amount":70,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","black pepper","handful of fresh parsley"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Soften the diced onion in the olive oil for 4 minutes, add the sliced garlic and oregano, then the chopped tomatoes, and simmer for 8 minutes","Add the shrimp and cook for 3 minutes until pink","Crumble in the feta, let it soften for 1 minute and serve with the rice, pepper and parsley"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","shrimp","chopped tomatoes","feta","onion","garlic","olive oil","rice","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Скариди с домати и фета","description":"Скариди, задушени в доматен сос с чесън и фета, с ориз","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Задушете нарязания на кубчета лук в зехтина за 4 минути, добавете нарязания чесън и ригана, след това нарязаните домати и варете на тих огън 8 минути","Добавете скаридите и гответе 3 минути, докато порозовеят","Натрошете фетата в соса, оставете я да омекне 1 минута и поднесете с ориза, пипер и магданоз"],"seasonings":["1 ч.л. сух риган","черен пипер","шепа пресен магданоз"]},"nl":{"name":"Garnalen met tomaat en feta","description":"Garnalen gestoofd in een tomatensaus met knoflook en feta, met rijst","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Bak de blokjes ui 4 minuten zacht in de olijfolie, voeg de plakjes knoflook en de oregano toe, dan de tomatenblokjes, en laat 8 minuten zachtjes koken","Voeg de garnalen toe en bak 3 minuten tot ze roze zijn","Verkruimel de feta erboven, laat hem 1 minuut zacht worden en serveer met de rijst, peper en peterselie"],"seasonings":["1 tl gedroogde oregano","zwarte peper","handje verse peterselie"]}}'::jsonb, 106),
  ('d-turkey-kofta-rice', 'Turkey Kofta with Rice and Yogurt', 'Herbed turkey kofta with rice, cucumber, tomato and yogurt', 'dinner', 'turkey mince', '🦃', 25, 'balanced', 638, 41, 66, 24, 2, 7, 139, '[{"name":"turkey mince","amount":160,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"yogurt","amount":80,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Mix the turkey mince with the cumin, oregano, salt and pepper and shape into {4} small patties","Fry them in the olive oil over medium heat for 4 to 5 minutes per side until cooked through","Serve with the rice, diced cucumber and tomato and the yogurt"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","light","turkey mince","rice","yogurt","cucumber","tomato","olive oil","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Пуешка кофта с ориз и кисело мляко","description":"Пуешка кофта с билки, ориз, краставица, домат и кисело мляко","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Смесете пуешката кайма с кимиона, ригана, сол и пипер и оформете {4} малки кюфтенца","Изпържете ги в зехтина на среден огън по 4–5 минути от всяка страна, докато се сготвят","Поднесете с ориза, нарязаните на кубчета краставица и домат и киселото мляко"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. сух риган","сол","черен пипер"]},"nl":{"name":"Kalkoenkofta met rijst en yoghurt","description":"Kofta van kalkoen met kruiden, rijst, komkommer, tomaat en yoghurt","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Meng het kalkoengehakt met de komijn, de oregano, zout en peper en vorm er {4} kleine burgertjes van","Bak ze in de olijfolie op middelhoog vuur 4 tot 5 minuten per kant gaar","Serveer met de rijst, de blokjes komkommer en tomaat en de yoghurt"],"seasonings":["1 tl gemalen komijn","1 tl gedroogde oregano","zout","zwarte peper"]}}'::jsonb, 107),
  ('d-mujadara', 'Mujadara', 'Lentils and rice with deeply caramelised onions and a tomato cucumber salad', 'dinner', 'lentils', '🧅', 45, 'weekend', 684, 24, 112, 17, 12, 11, 19, '[{"name":"lentils","amount":70,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"onion","amount":150,"unit":"g"},{"name":"olive oil","amount":15,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","{450} ml water","salt","black pepper"]'::jsonb, '["Slice the onion thinly and fry it in the olive oil over medium heat for 20 minutes, stirring often, until deep brown, then lift half onto a plate","Add the rinsed lentils, cumin and water to the pan and simmer for 10 minutes","Add the rice and salt, cover and cook on low heat for 15 minutes until the water is absorbed","Serve topped with the reserved onion, with the diced cucumber and tomato on the side"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","comfort","lentils","rice","onion","olive oil","cucumber","tomato","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Муджадара","description":"Леща и ориз със силно карамелизиран лук и салата от домат и краставица","instructions":["Нарежете лука на тънки филийки и го пържете в зехтина на среден огън 20 минути, като бъркате често, докато стане тъмнокафяв, след което прехвърлете половината в чиния","Добавете в тигана измитата леща, кимиона и водата и варете на тих огън 10 минути","Добавете ориза и сол, покрийте и гответе на слаб огън 15 минути, докато водата се поеме","Поднесете със запазения лук отгоре и нарязаните на кубчета краставица и домат отстрани"],"seasonings":["1 ч.л. смлян кимион","{450} мл вода","сол","черен пипер"]},"nl":{"name":"Mujadara","description":"Linzen en rijst met diepbruin gekaramelliseerde uien en een salade van tomaat en komkommer","instructions":["Snijd de ui in dunne ringen en bak hem 20 minuten in de olijfolie op middelhoog vuur diepbruin; roer vaak en schep dan de helft op een bord","Voeg de afgespoelde linzen, de komijn en het water toe aan de pan en laat 10 minuten zachtjes koken","Voeg de rijst en zout toe, dek af en kook 15 minuten op laag vuur tot het water is opgenomen","Serveer met de apart gehouden ui erop en de blokjes komkommer en tomaat ernaast"],"seasonings":["1 tl gemalen komijn","{450} ml water","zout","zwarte peper"]}}'::jsonb, 108),
  ('d-ratatouille-baked-eggs', 'Ratatouille with Baked Eggs', 'Zucchini, peppers and tomato stew with eggs and potatoes', 'dinner', 'eggs', '🍆', 40, 'balanced', 550, 24, 65, 24, 14, 20, 477, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"zucchini","amount":150,"unit":"g"},{"name":"peppers","amount":120,"unit":"g"},{"name":"chopped tomatoes","amount":250,"unit":"g"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp dried thyme or oregano","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes and drain","Dice the onion, zucchini and peppers and cook them in the olive oil for 8 minutes, then add the sliced garlic and thyme","Add the chopped tomatoes and simmer for 12 minutes until thick, then season","Make {n:eggs} wells, crack in the eggs, cover and cook 5 minutes until set, and serve with the potatoes"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","light","eggs","zucchini","peppers","chopped tomatoes","potatoes","onion","garlic","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Рататуй с яйца","description":"Яхния от тиквичка, чушки и домати с яйца и картофи","instructions":["Сварете картофите, нарязани на парчета, в подсолена вода за 15 минути и ги отцедете","Нарежете лука, тиквичката и чушките на кубчета и ги гответе в зехтина 8 минути, след което добавете нарязания чесън и мащерката","Добавете нарязаните домати и варете на тих огън 12 минути, докато се сгъсти, след което овкусете","Направете {n:eggs} гнезда, чукнете яйцата в тях, покрийте и гответе 5 минути, докато стегнат, и поднесете с картофите"],"seasonings":["1 ч.л. суха мащерка или риган","сол","черен пипер"]},"nl":{"name":"Ratatouille met eieren","description":"Stoof van courgette, paprika en tomaat met eieren en aardappelen","instructions":["Kook de aardappelen, in stukken gesneden, 15 minuten in water met zout en giet af","Snijd de ui, de courgette en de paprika in blokjes en bak ze 8 minuten in de olijfolie; voeg dan de plakjes knoflook en de tijm toe","Voeg de tomatenblokjes toe en laat 12 minuten zachtjes koken tot de saus dik is; breng op smaak","Maak {n:eggs} kuiltjes, breek de eieren erin, dek af en laat 5 minuten garen tot ze gestold zijn; serveer met de aardappelen"],"seasonings":["1 tl gedroogde tijm of oregano","zout","zwarte peper"]}}'::jsonb, 109),
  ('d-tofu-souvlaki-bowl', 'Tofu Souvlaki Bowl', 'Lemon-oregano tofu over couscous with cucumber, tomato and peppers', 'dinner', 'tofu', '🥙', 20, 'quick', 691, 43, 75, 29, 12, 8, 43, '[{"name":"tofu","amount":180,"unit":"g"},{"name":"couscous","amount":70,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["2 tsp dried oregano","{90} ml boiling water","salt","black pepper"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Cut the tofu into cubes, toss with the oregano, salt, pepper and half the juice of the lemon and fry in the olive oil for 6 minutes until golden","Dice the cucumber, tomato and peppers","Serve the tofu over the couscous with the raw vegetables and the rest of the lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","tofu","couscous","cucumber","tomato","peppers","olive oil","lemon","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Сувлаки купа с тофу","description":"Тофу с лимон и риган върху кускус с краставица, домат и чушки","instructions":["Залейте кускуса с врящата вода и щипка сол, покрийте за 5 минути и го разрохкайте с вилица","Нарежете тофуто на кубчета, разбъркайте го с ригана, сол, пипер и половината от сока от лимона и го запържете в зехтина за 6 минути до златисто","Нарежете краставицата, домата и чушките на кубчета","Поднесете тофуто върху кускуса с пресните зеленчуци и останалия лимонов сок"],"seasonings":["2 ч.л. сух риган","{90} мл вряща вода","сол","черен пипер"]},"nl":{"name":"Souvlakibowl met tofu","description":"Tofu met citroen en oregano op couscous met komkommer, tomaat en paprika","instructions":["Giet het kokende water over de couscous met een snufje zout, dek 5 minuten af en maak los met een vork","Snijd de tofu in blokjes, meng ze met de oregano, zout, peper en de helft van het sap van de citroen en bak ze 6 minuten in de olijfolie goudbruin","Snijd de komkommer, de tomaat en de paprika in blokjes","Serveer de tofu op de couscous met de rauwe groenten en de rest van het citroensap"],"seasonings":["2 tl gedroogde oregano","{90} ml kokend water","zout","zwarte peper"]}}'::jsonb, 110),
  ('d-beef-chickpea-tagine', 'Beef and Chickpea Tagine', 'Slow-cooked spiced beef with chickpeas and carrots, served with couscous', 'dinner', 'beef', '🥘', 75, 'weekend', 755, 51, 93, 19, 15, 13, 562, '[{"name":"beef","amount":150,"unit":"g"},{"name":"chickpeas","amount":80,"unit":"g"},{"name":"couscous","amount":75,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp cinnamon","1/2 tsp chili flakes","{250} ml water","salt"]'::jsonb, '["Cut the beef into chunks and brown it in the olive oil for 4 minutes, then add the diced onion for 3 minutes","Stir in the cumin, paprika, cinnamon and chili flakes, then the chopped tomatoes, sliced carrots and water","Cover and simmer on low heat for 50 to 60 minutes until the beef is tender, adding the drained chickpeas for the last 10 minutes","Pour {100} ml boiling water over the couscous with a pinch of salt, cover for 5 minutes, fluff and serve with the tagine"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","comfort","hearty","beef","chickpeas","couscous","chopped tomatoes","carrots","onion","olive oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Тажин с телешко и нахут","description":"Бавно сготвено телешко с подправки, нахут и моркови, с кускус","instructions":["Нарежете телешкото на парчета и го запържете в зехтина за 4 минути, след което добавете нарязания на кубчета лук за 3 минути","Добавете кимиона, червения пипер, канелата и люспите чили, а след тях нарязаните домати, нарязаните моркови и водата","Покрийте и варете на слаб огън 50–60 минути, докато телешкото омекне, като през последните 10 минути добавите отцедения нахут","Залейте кускуса с {100} мл вряща вода и щипка сол, покрийте за 5 минути, разрохкайте го и го поднесете с тажина"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","1/2 ч.л. канела","1/2 ч.л. люспи чили","{250} мл вода","сол"]},"nl":{"name":"Tajine met rundvlees en kikkererwten","description":"Langzaam gegaard gekruid rundvlees met kikkererwten en wortel, met couscous","instructions":["Snijd het rundvlees in stukken en bak het 4 minuten bruin in de olijfolie; bak dan de blokjes ui 3 minuten mee","Roer de komijn, het paprikapoeder, de kaneel en de chilivlokken erdoor en dan de tomatenblokjes, de plakjes wortel en het water","Dek af en laat 50 tot 60 minuten op laag vuur zachtjes koken tot het vlees mals is; voeg de laatste 10 minuten de uitgelekte kikkererwten toe","Giet {100} ml kokend water over de couscous met een snufje zout, dek 5 minuten af, maak los en serveer bij de tajine"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","1/2 tl kaneel","1/2 tl chilivlokken","{250} ml water","zout"]}}'::jsonb, 111),
  ('d-salmon-nicoise-salad', 'Salmon Niçoise Salad', 'Warm salmon with potatoes, green beans, egg, tomato and lettuce', 'dinner', 'salmon', '🥗', 25, 'balanced', 670, 43, 48, 35, 9, 8, 188, '[{"name":"salmon","amount":140,"unit":"g"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"green beans","amount":100,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"tomato","amount":100,"unit":"g"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp mustard","splash of red wine vinegar","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, for 15 minutes, adding the egg for the last 8 minutes and the green beans for the last 5, then drain","Fry the salmon in a little of the olive oil for 3 to 4 minutes per side","Whisk the remaining olive oil with the mustard, vinegar, salt and pepper","Arrange the lettuce, potatoes, beans, tomato wedges and quartered egg on a plate, top with the salmon and pour over the dressing"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","salmon","potatoes","green beans","eggs","tomato","lettuce","olive oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Салата „Нисоаз“ със сьомга","description":"Топла сьомга с картофи, зелен фасул, яйце, домат и маруля","instructions":["Сварете картофите, нарязани на парчета, за 15 минути, като през последните 8 минути добавите яйцето, а през последните 5 – зеления фасул, и отцедете","Изпържете сьомгата в малко от зехтина по 3–4 минути от всяка страна","Разбийте останалия зехтин с горчицата, оцета, сол и пипер","Подредете в чиния марулята, картофите, фасула, резените домат и яйцето на четвъртинки, сложете сьомгата отгоре и полейте с дресинга"],"seasonings":["1 ч.л. горчица","малко червен винен оцет","сол","черен пипер"]},"nl":{"name":"Salade niçoise met zalm","description":"Warme zalm met aardappelen, sperziebonen, ei, tomaat en sla","instructions":["Kook de aardappelen, in stukken gesneden, 15 minuten; kook het ei de laatste 8 minuten mee en de sperziebonen de laatste 5 en giet af","Bak de zalm 3 tot 4 minuten per kant in een beetje van de olijfolie","Klop de rest van de olijfolie met de mosterd, de azijn, zout en peper","Verdeel de sla, de aardappelen, de bonen, de tomatenpartjes en het ei in vieren over een bord, leg de zalm erop en giet de dressing erover"],"seasonings":["1 tl mosterd","scheutje rodewijnazijn","zout","zwarte peper"]}}'::jsonb, 112),
  ('d-lemon-garlic-chicken-potatoes', 'Lemon Garlic Chicken with Potatoes and Green Beans', 'Pan-roasted chicken with boiled potatoes and green beans', 'dinner', 'chicken', '🍋', 30, 'balanced', 608, 48, 69, 17, 11, 8, 104, '[{"name":"chicken","amount":170,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":12,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp dried thyme","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the green beans for the last 5, then drain","Season the chicken with the thyme, salt and pepper and fry it in the oil over medium heat for 6 minutes per side","Add the sliced garlic and the juice of the lemon to the pan for the last minute","Serve the chicken with the potatoes and beans and spoon over the pan juices"]'::jsonb, '["stovetop"]'::jsonb, '["light","chicken","potatoes","green beans","garlic","oil","lemon","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пилешко с лимон и чесън, картофи и зелен фасул","description":"Пилешко на тиган с варени картофи и зелен фасул","instructions":["Сварете картофите, нарязани на парчета, в подсолена вода за 15 минути, като през последните 5 добавите зеления фасул, и отцедете","Овкусете пилешкото с мащерката, сол и пипер и го изпържете в олиото на среден огън по 6 минути от всяка страна","През последната минута добавете в тигана нарязания чесън и сока от лимона","Поднесете пилешкото с картофите и фасула и полейте със соса от тигана"],"seasonings":["1 ч.л. суха мащерка","сол","черен пипер"]},"nl":{"name":"Kip met citroen en knoflook, aardappelen en sperziebonen","description":"In de pan gebakken kip met gekookte aardappelen en sperziebonen","instructions":["Kook de aardappelen, in stukken gesneden, 15 minuten in water met zout, kook de sperziebonen de laatste 5 minuten mee en giet af","Kruid de kip met de tijm, zout en peper en bak hem in de olie op middelhoog vuur 6 minuten per kant","Voeg de laatste minuut de plakjes knoflook en het sap van de citroen toe aan de pan","Serveer de kip met de aardappelen en de bonen en schep het bakvocht erover"],"seasonings":["1 tl gedroogde tijm","zout","zwarte peper"]}}'::jsonb, 113),
  ('d-cottage-pie', 'Cottage Pie', 'Beef mince with carrots and peas under a mashed potato top', 'dinner', 'beef mince', '🥧', 55, 'weekend', 737, 39, 74, 32, 11, 13, 304, '[{"name":"beef mince","amount":150,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"butter","amount":10,"unit":"g"},{"name":"milk","amount":40,"unit":"ml"},{"name":"tomato paste","amount":10,"unit":"g"}]'::jsonb, '["1 stock cube","{150} ml water","salt","black pepper"]'::jsonb, '["Heat the oven to 200°C and boil the potatoes, cut into chunks, for 15 minutes, then drain and mash with the butter and milk","Brown the beef mince with the diced onion and carrots in a dry pan for 8 minutes","Stir in the tomato paste, water and stock cube and simmer for 10 minutes, then add the peas","Tip into a small baking dish, spread the mash on top and bake for 20 minutes until golden"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","beef mince","potatoes","carrots","peas","onion","butter","milk","tomato paste","stovetop","oven","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Котидж пай","description":"Телешка кайма с моркови и грах под коричка от картофено пюре","instructions":["Загрейте фурната на 200°C и сварете картофите, нарязани на парчета, за 15 минути, след което ги отцедете и ги намачкайте с маслото и млякото","Запържете телешката кайма с нарязаните на кубчета лук и моркови в сух тиган за 8 минути","Добавете доматеното пюре, водата и кубчето бульон и варете на тих огън 10 минути, след което добавете граха","Изсипете в малка тава, разстелете пюрето отгоре и печете 20 минути до златисто"],"seasonings":["1 кубче бульон","{150} мл вода","сол","черен пипер"]},"nl":{"name":"Cottage pie","description":"Rundergehakt met wortel en doperwten onder een laag aardappelpuree","instructions":["Verwarm de oven voor op 200°C en kook de aardappelen, in stukken gesneden, 15 minuten; giet af en stamp ze fijn met de boter en de melk","Bak het rundergehakt 8 minuten bruin met de blokjes ui en wortel in een droge pan","Roer de tomatenpuree, het water en het bouillonblokje erdoor, laat 10 minuten zachtjes koken en voeg dan de doperwten toe","Schep in een kleine ovenschaal, verdeel de puree erover en bak 20 minuten goudbruin"],"seasonings":["1 bouillonblokje","{150} ml water","zout","zwarte peper"]}}'::jsonb, 114),
  ('d-salmon-mash-peas', 'Salmon with Mash and Peas', 'Pan-fried salmon with buttery mashed potatoes and peas', 'dinner', 'salmon', '🐟', 25, 'balanced', 714, 43, 71, 30, 12, 10, 278, '[{"name":"salmon","amount":150,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"peas","amount":80,"unit":"g"},{"name":"butter","amount":10,"unit":"g"},{"name":"milk","amount":40,"unit":"ml"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the peas for the last 2, then drain","Lift out the peas and mash the potatoes with the butter and milk","Season the salmon and fry it in a non-stick pan over medium heat for 3 to 4 minutes per side","Serve with the mash, peas and the lemon cut into wedges"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","salmon","potatoes","peas","butter","milk","lemon","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Сьомга с пюре и грах","description":"Сьомга на тиган с маслено картофено пюре и грах","instructions":["Сварете картофите, нарязани на парчета, в подсолена вода за 15 минути, като през последните 2 добавите граха, и отцедете","Извадете граха и намачкайте картофите с маслото и млякото","Овкусете сьомгата и я изпържете в незалепващ тиган на среден огън по 3–4 минути от всяка страна","Поднесете с пюрето, граха и лимона, нарязан на резени"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Zalm met puree en doperwten","description":"Gebakken zalm met romige aardappelpuree en doperwten","instructions":["Kook de aardappelen, in stukken gesneden, 15 minuten in water met zout, kook de doperwten de laatste 2 minuten mee en giet af","Schep de doperwten eruit en stamp de aardappelen fijn met de boter en de melk","Kruid de zalm en bak hem in een koekenpan met antiaanbaklaag op middelhoog vuur 3 tot 4 minuten per kant","Serveer met de puree, de doperwten en de citroen in partjes"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 115),
  ('d-chicken-spinach-curry', 'Chicken and Spinach Curry', 'Tomato-based chicken curry with spinach and yogurt, served with rice', 'dinner', 'chicken', '🍛', 35, 'balanced', 664, 49, 82, 16, 8, 11, 416, '[{"name":"chicken","amount":160,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"spinach","amount":100,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"yogurt","amount":60,"unit":"g"},{"name":"rice","amount":75,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","1/2 tsp chili flakes","1 tsp grated ginger","salt"]'::jsonb, '["Dice the onion and soften it in the oil for 5 minutes, then add the chopped garlic, ginger, curry powder and chili flakes for 1 minute","Add the chicken in chunks and cook for 3 minutes, then the chopped tomatoes, and simmer for 15 minutes","Meanwhile boil the rice in salted water for 10 to 12 minutes and drain","Stir the spinach into the curry until wilted, take it off the heat, stir in the yogurt and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["spicy","comfort","chicken","chopped tomatoes","spinach","onion","garlic","yogurt","rice","oil","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Къри с пилешко и спанак","description":"Пилешко къри на доматена основа със спанак и кисело мляко, с ориз","instructions":["Нарежете лука на кубчета и го задушете в олиото за 5 минути, след което добавете накълцания чесън, джинджифила, кърито и люспите чили за 1 минута","Добавете пилешкото на парчета и гответе 3 минути, след това нарязаните домати и варете на тих огън 15 минути","Междувременно сварете ориза в подсолена вода за 10–12 минути и го отцедете","Добавете спанака към кърито и бъркайте, докато омекне, свалете от огъня, разбъркайте киселото мляко и поднесете с ориза"],"seasonings":["1 с.л. къри на прах","1/2 ч.л. люспи чили","1 ч.л. настърган джинджифил","сол"]},"nl":{"name":"Curry met kip en spinazie","description":"Kipcurry op basis van tomaat met spinazie en yoghurt, met rijst","instructions":["Snijd de ui in blokjes en bak hem 5 minuten zacht in de olie; voeg dan de gehakte knoflook, de gember, het kerriepoeder en de chilivlokken 1 minuut toe","Voeg de kip in stukken toe en bak 3 minuten, dan de tomatenblokjes, en laat 15 minuten zachtjes koken","Kook intussen de rijst 10 tot 12 minuten in water met zout en giet af","Roer de spinazie door de curry tot hij geslonken is, haal van het vuur, roer de yoghurt erdoor en serveer met de rijst"],"seasonings":["1 el kerriepoeder","1/2 tl chilivlokken","1 tl geraspte gember","zout"]}}'::jsonb, 116),
  ('d-pork-mustard-cream-mash', 'Pork in Mustard Cream Sauce with Mash', 'Pork medallions in a creamy mustard sauce with mash and green beans', 'dinner', 'pork', '🥔', 30, 'balanced', 644, 44, 62, 25, 9, 8, 183, '[{"name":"pork","amount":160,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"cream sauce","amount":60,"unit":"g"},{"name":"green beans","amount":100,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["2 tsp mustard","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the green beans for the last 5, then drain","Lift out the beans and mash the potatoes with the butter","Slice the pork into medallions, season and fry in a non-stick pan for 3 minutes per side","Stir the cream sauce and mustard into the pan, simmer for 2 minutes and serve over the pork with the mash and beans"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","light","pork","potatoes","cream sauce","green beans","butter","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Свинско в сметанов сос с горчица и пюре","description":"Свински медальони в кремообразен сос с горчица, с пюре и зелен фасул","instructions":["Сварете картофите, нарязани на парчета, в подсолена вода за 15 минути, като през последните 5 добавите зеления фасул, и отцедете","Извадете фасула и намачкайте картофите с маслото","Нарежете свинското на медальони, овкусете ги и ги изпържете в незалепващ тиган по 3 минути от всяка страна","Добавете в тигана сметановия сос и горчицата, варете на тих огън 2 минути и поднесете върху свинското с пюрето и фасула"],"seasonings":["2 ч.л. горчица","сол","черен пипер"]},"nl":{"name":"Varkensvlees in mosterdroomsaus met puree","description":"Varkensmedaillons in een romige mosterdsaus met puree en sperziebonen","instructions":["Kook de aardappelen, in stukken gesneden, 15 minuten in water met zout, kook de sperziebonen de laatste 5 minuten mee en giet af","Schep de bonen eruit en stamp de aardappelen fijn met de boter","Snijd het varkensvlees in medaillons, kruid ze en bak ze in een koekenpan met antiaanbaklaag 3 minuten per kant","Roer de roomsaus en de mosterd door de pan, laat 2 minuten zachtjes koken en serveer over het vlees met de puree en de bonen"],"seasonings":["2 tl mosterd","zout","zwarte peper"]}}'::jsonb, 117),
  ('d-slow-cooker-beef-stew', 'Slow Cooker Beef Stew', 'Tender beef with potatoes, carrots and peas in a rich gravy', 'dinner', 'beef', '🍲', 240, 'weekend', 638, 48, 76, 16, 12, 14, 245, '[{"name":"beef","amount":170,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"carrots","amount":100,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"tomato paste","amount":15,"unit":"g"},{"name":"flour","amount":10,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 stock cube","{300} ml water","1 tsp dried thyme","salt","black pepper"]'::jsonb, '["Cut the beef into chunks, toss it in the flour and brown it in the oil in a pan for 4 minutes","Put it in the slow cooker with the potatoes and carrots in chunks, the diced onion, tomato paste, water, stock cube and thyme","Cook on high for 4 hours or on low for 7 to 8 hours until the beef falls apart","Stir in the peas for the last 10 minutes and season"]'::jsonb, '["stovetop","slow cooker"]'::jsonb, '["comfort","light","beef","potatoes","carrots","onion","peas","tomato paste","flour","oil","stovetop","slow cooker","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Телешка яхния в уред за бавно готвене","description":"Крехко телешко с картофи, моркови и грах в плътен сос","instructions":["Нарежете телешкото на парчета, овалвайте го в брашното и го запържете в олиото в тиган за 4 минути","Сложете го в уреда за бавно готвене с картофите и морковите на парчета, нарязания на кубчета лук, доматеното пюре, водата, кубчето бульон и мащерката","Гответе на висока степен 4 часа или на ниска степен 7–8 часа, докато телешкото започне да се разпада","Добавете граха през последните 10 минути и овкусете"],"seasonings":["1 кубче бульон","{300} мл вода","1 ч.л. суха мащерка","сол","черен пипер"]},"nl":{"name":"Runderstoof uit de slowcooker","description":"Mals rundvlees met aardappelen, wortel en doperwten in een volle jus","instructions":["Snijd het rundvlees in stukken, wentel ze door de bloem en bak ze 4 minuten bruin in de olie in een pan","Doe het in de slowcooker met de aardappelen en de wortels in stukken, de blokjes ui, de tomatenpuree, het water, het bouillonblokje en de tijm","Gaar 4 uur op de hoge stand of 7 tot 8 uur op de lage stand, tot het vlees uit elkaar valt","Roer de laatste 10 minuten de doperwten erdoor en breng op smaak"],"seasonings":["1 bouillonblokje","{300} ml water","1 tl gedroogde tijm","zout","zwarte peper"]}}'::jsonb, 118),
  ('d-oven-fish-and-chips', 'Oven Fish and Chips', 'Crisp-coated white fish with oven chips and peas', 'dinner', 'white fish', '🍟', 40, 'balanced', 762, 52, 90, 22, 13, 9, 284, '[{"name":"white fish","amount":180,"unit":"g"},{"name":"potatoes","amount":350,"unit":"g"},{"name":"peas","amount":80,"unit":"g"},{"name":"flour","amount":15,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"oil","amount":15,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","1/2 tsp paprika"]'::jsonb, '["Heat the oven to 220°C, cut the potatoes into chips, toss with two thirds of the oil and salt and roast for 30 minutes, turning once","Season the fish and coat it in the flour mixed with the paprika, then the beaten egg, then the flour again","Fry it in the remaining oil over medium-high heat for 3 minutes per side until golden","Boil the peas for 2 minutes and serve everything with the lemon cut into wedges"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","hearty","white fish","potatoes","peas","flour","eggs","oil","lemon","stovetop","oven","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Риба с картофи на фурна","description":"Бяла риба с хрупкава панировка, картофи на фурна и грах","instructions":["Загрейте фурната на 220°C, нарежете картофите на пръчици, разбъркайте ги с две трети от олиото и сол и ги печете 30 минути, като ги обърнете веднъж","Овкусете рибата и я овалвайте в брашното, смесено с червения пипер, след това в разбитото яйце и отново в брашното","Изпържете я в останалото олио на умерено силен огън по 3 минути от всяка страна до златисто","Сварете граха за 2 минути и поднесете всичко с лимона, нарязан на резени"],"seasonings":["сол","черен пипер","1/2 ч.л. червен пипер"]},"nl":{"name":"Fish and chips uit de oven","description":"Witvis met een krokant laagje, ovenfrieten en doperwten","instructions":["Verwarm de oven voor op 220°C, snijd de aardappelen in frieten, meng ze met twee derde van de olie en zout en rooster ze 30 minuten; keer één keer","Kruid de vis en wentel hem door de bloem gemengd met het paprikapoeder, dan door het losgeklopte ei en dan nog eens door de bloem","Bak hem in de rest van de olie op middelhoog tot hoog vuur 3 minuten per kant goudbruin","Kook de doperwten 2 minuten en serveer alles met de citroen in partjes"],"seasonings":["zout","zwarte peper","1/2 tl paprikapoeder"]}}'::jsonb, 119)
